:root {
  --cyan: #5ff6ff;
  --cyan-dim: #2fb8c8;
  --amber: #ffb43c;
  --amber-hot: #ff7a1a;
  --pink: #ff2e88;
  --danger: #ff4d5e;
  --ink: #05070c;
  --glass: rgba(8, 16, 24, 0.55);
  --line: rgba(95, 246, 255, 0.22);
  --text: #d9f6fa;
  --muted: rgba(180, 220, 228, 0.58);
  --font: "Chakra Petch", "Rajdhani", "Segoe UI", "Trebuchet MS", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #05070c;
  color: var(--text);
  font-family: var(--font);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 35%, rgba(30, 90, 110, 0.35), transparent 55%),
    radial-gradient(ellipse at 80% 80%, rgba(120, 20, 80, 0.18), transparent 50%),
    #05070c;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

/* ---------------- overlays / treatment ---------------- */

#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 4;
  background:
    radial-gradient(ellipse at center, transparent 46%, rgba(0, 0, 0, 0.38) 82%, rgba(0, 0, 0, 0.72) 100%),
    linear-gradient(to bottom, rgba(0,0,0,0.32), transparent 14%, transparent 82%, rgba(0,0,0,0.42));
  mix-blend-mode: multiply;
}

#scanlines {
  position: absolute; inset: 0; pointer-events: none; z-index: 5; opacity: 0.16;
  background: repeating-linear-gradient(to bottom, rgba(255,255,255,0.045) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
}

#rain-glass {
  position: absolute; inset: 0; pointer-events: none; z-index: 3; opacity: 0.34;
  background-image:
    radial-gradient(ellipse 12px 20px at 15% 25%, rgba(160, 230, 255, 0.12), transparent 60%),
    radial-gradient(ellipse 8px 15px at 72% 12%, rgba(160, 230, 255, 0.10), transparent 60%),
    radial-gradient(ellipse 10px 18px at 88% 62%, rgba(160, 230, 255, 0.09), transparent 60%),
    radial-gradient(ellipse 7px 12px at 33% 78%, rgba(160, 230, 255, 0.10), transparent 60%),
    radial-gradient(ellipse 16px 26px at 56% 42%, rgba(160, 230, 255, 0.06), transparent 60%);
  filter: blur(0.4px);
}

#damage-flash {
  position: absolute; inset: 0; pointer-events: none; z-index: 6;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(255, 30, 54, 0.55) 100%);
  opacity: 0;
  transition: opacity 0.35s ease-out;
}
#damage-flash.hit { opacity: 1; transition: opacity 0.06s ease-out; }

#heal-flash {
  position: absolute; inset: 0; pointer-events: none; z-index: 6;
  background: radial-gradient(ellipse at center, transparent 40%, rgba(60, 255, 200, 0.18) 100%);
  opacity: 0; transition: opacity 0.5s ease-out;
}
#heal-flash.on { opacity: 1; transition: opacity 0.12s ease-out; }

#damage-directions { position: absolute; inset: 0; pointer-events: none; z-index: 6; }
.damage-dir {
  position: absolute; left: 50%; top: 50%; width: 240px; height: 240px;
  margin: -120px 0 0 -120px; border-radius: 50%;
  border-top: 5px solid rgba(255, 70, 80, 0.85);
  filter: drop-shadow(0 0 8px rgba(255, 40, 60, 0.9));
  transform-origin: 50% 50%;
  animation: dmgFade 1s ease-out forwards;
  clip-path: polygon(0 0, 100% 0, 100% 42%, 0 42%);
}
@keyframes dmgFade { from { opacity: 1; } to { opacity: 0; } }

/* ---------------- HUD ---------------- */

#hud {
  position: absolute; inset: 0; z-index: 7; pointer-events: none;
  padding: max(18px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
  display: flex; flex-direction: column; justify-content: space-between;
  text-shadow: 0 0 12px rgba(0, 180, 210, 0.35);
}

.glass-panel {
  background: linear-gradient(135deg, rgba(9, 20, 29, 0.72), rgba(6, 11, 18, 0.42));
  border: 1px solid var(--line);
  box-shadow: inset 0 0 24px rgba(70, 230, 255, 0.04), 0 6px 30px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

#hud-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }

.brand-block { display: flex; align-items: center; gap: 11px; min-width: 220px; }
.brand-mark { color: var(--amber); font-size: 24px; line-height: 1; text-shadow: 0 0 18px var(--amber); }
.brand { font-size: 19px; font-weight: 800; letter-spacing: 0.26em; color: #eafcff; }
.brand-sub { font-size: 8.5px; letter-spacing: 0.32em; color: var(--muted); margin-top: 3px; }

#objective {
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 8px 26px 9px; clip-path: polygon(12px 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 12px 100%, 0 50%);
  border-left: none; border-right: none;
  min-width: 310px;
}
.obj-label { font-size: 8px; letter-spacing: 0.42em; color: var(--amber); }
#objective-text { font-size: 13px; letter-spacing: 0.2em; font-weight: 700; }
#objective-sub { font-size: 8px; letter-spacing: 0.18em; color: var(--muted); }

.top-right { display: flex; justify-content: flex-end; min-width: 220px; }
#radar-wrap { position: relative; width: 136px; height: 136px; padding: 4px; border-radius: 50%; overflow: hidden; }
#radar { width: 100%; height: 100%; display: block; border-radius: 50%; }
.radar-label {
  position: absolute; bottom: 8px; left: 0; right: 0; text-align: center;
  font-size: 7px; letter-spacing: 0.24em; color: var(--muted);
}

#wave-banner {
  position: absolute; left: 50%; top: 96px; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  opacity: 0; transition: opacity 0.5s ease;
  text-align: center; pointer-events: none;
}
#wave-banner.show { opacity: 1; }
#wave-kicker { font-size: 9px; letter-spacing: 0.5em; color: var(--amber); }
#wave-title {
  font-size: 38px; letter-spacing: 0.16em; font-weight: 800; line-height: 1.05;
  color: #fff; text-shadow: 0 0 26px rgba(255, 140, 40, 0.55), 0 2px 0 rgba(0,0,0,0.5);
}
#wave-sub { font-size: 9px; letter-spacing: 0.3em; color: var(--muted); }

#score-strip {
  position: absolute; left: 50%; top: 52%; transform: translateX(-50%);
  display: none;
}

#hitmarker { position: absolute; left: 50%; top: 50%; width: 44px; height: 44px; margin: -22px 0 0 -22px; opacity: 0; transition: opacity 0.12s; }
#hitmarker.show { opacity: 1; }
#hitmarker.kill i { background: var(--danger); box-shadow: 0 0 10px var(--danger); }
#hitmarker i { position: absolute; width: 12px; height: 2px; background: #fff; box-shadow: 0 0 8px rgba(255,255,255,0.9); }
#hitmarker i:nth-child(1) { left: 2px; top: 8px; transform: rotate(45deg); }
#hitmarker i:nth-child(2) { right: 2px; top: 8px; transform: rotate(-45deg); }
#hitmarker i:nth-child(3) { left: 2px; bottom: 8px; transform: rotate(-45deg); }
#hitmarker i:nth-child(4) { right: 2px; bottom: 8px; transform: rotate(45deg); }

#crosshair {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px;
  --gap: 7px; --len: 8px;
}
#crosshair i { position: absolute; background: rgba(220, 255, 255, 0.9); box-shadow: 0 0 6px rgba(95,246,255,0.8); transition: transform 0.06s; }
#crosshair .ch-t { left: 23px; top: calc(24px - var(--gap) - var(--len)); width: 2px; height: var(--len); }
#crosshair .ch-b { left: 23px; bottom: calc(24px - var(--gap) - var(--len)); width: 2px; height: var(--len); }
#crosshair .ch-l { top: 23px; left: calc(24px - var(--gap) - var(--len)); height: 2px; width: var(--len); }
#crosshair .ch-r { top: 23px; right: calc(24px - var(--gap) - var(--len)); height: 2px; width: var(--len); }
#crosshair .ch-dot { position: absolute; left: 22px; top: 22px; width: 4px; height: 4px; border-radius: 50%; background: var(--amber); box-shadow: 0 0 8px var(--amber); }
#crosshair.ads i { opacity: 0.25; }
#crosshair.ads .ch-dot { background: #fff; }

#reload-ring {
  position: absolute; left: 50%; top: 50%; width: 76px; height: 76px; margin: -38px 0 0 -38px;
  opacity: 0; transition: opacity 0.15s;
}
#reload-ring.show { opacity: 1; }
#reload-ring svg { width: 100%; height: 100%; transform: rotate(-90deg); }
#reload-ring circle { fill: none; stroke-width: 2.2; }
#reload-ring circle:first-child { stroke: rgba(95,246,255,0.14); }
#reload-progress { stroke: var(--amber); stroke-linecap: round; stroke-dasharray: 113; stroke-dashoffset: 113; filter: drop-shadow(0 0 6px var(--amber)); }

#kill-feed {
  position: absolute; right: 26px; top: 34%; display: flex; flex-direction: column; align-items: flex-end; gap: 5px;
}
.feed-item {
  display: flex; align-items: center; gap: 8px; padding: 5px 10px;
  background: linear-gradient(90deg, transparent, rgba(7, 16, 24, 0.72));
  border-right: 2px solid var(--amber);
  font-size: 10px; letter-spacing: 0.12em; color: #cfeff5;
  animation: feedIn 0.22s ease-out, feedOut 0.4s 2.6s forwards;
}
.feed-item .tag { color: var(--amber); font-weight: 700; }
.feed-item .pts { color: var(--cyan); }
@keyframes feedIn { from { transform: translateX(30px); opacity: 0; } }
@keyframes feedOut { to { opacity: 0; transform: translateX(24px); } }

#damage-numbers { position: absolute; inset: 0; overflow: hidden; }
.dmg-num {
  position: absolute; font-weight: 800; font-size: 17px; color: #fff;
  text-shadow: 0 0 10px rgba(255, 170, 60, 0.9), 0 2px 4px rgba(0,0,0,0.7);
  transform: translate(-50%, -50%); animation: dmgNum 0.7s ease-out forwards; white-space: nowrap;
}
.dmg-num.crit { color: var(--amber); font-size: 22px; }
@keyframes dmgNum {
  0% { opacity: 0; transform: translate(-50%, -30%) scale(0.7); }
  16% { opacity: 1; transform: translate(-50%, -55%) scale(1.15); }
  100% { opacity: 0; transform: translate(-50%, -120%) scale(1); }
}

#center-toast {
  position: absolute; left: 50%; top: 63%; transform: translateX(-50%);
  font-size: 11px; letter-spacing: 0.34em; color: var(--amber);
  opacity: 0; transition: opacity 0.25s; text-align: center;
}
#center-toast.show { opacity: 1; }

#hud-bottom { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; }

.vitals { width: min(360px, 34vw); padding: 12px 16px 10px; clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 50%, calc(100% - 14px) 100%, 0 100%); }
.vitals-row { margin-bottom: 7px; }
.vital-label { display: flex; justify-content: space-between; align-items: baseline; font-size: 8.5px; letter-spacing: 0.3em; color: var(--muted); margin-bottom: 4px; }
.vital-label b { font-size: 17px; letter-spacing: 0.06em; color: #effeFF; }
.bar { position: relative; height: 9px; background: rgba(120, 210, 230, 0.08); border: 1px solid rgba(95, 246, 255, 0.14); overflow: hidden; }
#health-bar { position: absolute; inset: 0; width: 100%; background: linear-gradient(90deg, #34e6c6, #87fbff 70%, #ffffff); box-shadow: 0 0 14px rgba(80, 255, 220, 0.6); transition: width 0.24s ease, background 0.3s; }
#health-bar.low { background: linear-gradient(90deg, #ff3b4e, #ff8a4a); box-shadow: 0 0 16px rgba(255, 60, 70, 0.7); }
.bar-segments { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 12%, rgba(5, 10, 16, 0.72) 12% 13.5%); }
.bar.armor { height: 6px; }
#armor-bar { position: absolute; inset: 0; width: 100%; background: linear-gradient(90deg, #2f8fff, #69d9ff); box-shadow: 0 0 12px rgba(70, 170, 255, 0.6); transition: width 0.24s ease; }
.armor-row .vital-label b { font-size: 13px; color: #9adfff; }
.status-line { display: flex; align-items: center; gap: 6px; margin-top: 8px; font-size: 7.5px; letter-spacing: 0.24em; color: rgba(140, 210, 220, 0.55); }
.status-dot { width: 5px; height: 5px; border-radius: 50%; background: #55ffcf; box-shadow: 0 0 8px #55ffcf; animation: pulse 2s infinite; }
@keyframes pulse { 50% { opacity: 0.35; } }

.weapon-block { text-align: right; min-width: 230px; padding-bottom: 4px; }
.weapon-name { font-size: 12px; font-weight: 700; letter-spacing: 0.22em; color: #eafcff; }
.weapon-name span { color: var(--muted); font-weight: 400; }
.weapon-mode { font-size: 7.5px; letter-spacing: 0.24em; color: var(--amber); margin-top: 2px; }
.ammo-row { display: flex; align-items: baseline; justify-content: flex-end; gap: 5px; line-height: 0.9; margin-top: 3px; }
#ammo { font-size: 48px; font-weight: 800; letter-spacing: 0.02em; color: #fff; text-shadow: 0 0 22px rgba(95, 246, 255, 0.4); }
#ammo.low { color: var(--amber); text-shadow: 0 0 20px rgba(255, 140, 40, 0.7); }
.ammo-slash { font-size: 18px; color: rgba(150, 220, 230, 0.4); }
#ammo-reserve { font-size: 16px; color: var(--muted); letter-spacing: 0.1em; }
.reload-bar { height: 2px; background: rgba(95,246,255,0.1); margin-top: 6px; margin-left: auto; width: 76%; }
#reload-bar-fill { height: 100%; width: 0%; background: var(--amber); box-shadow: 0 0 8px var(--amber); }
.weapon-hint { margin-top: 6px; font-size: 7px; letter-spacing: 0.22em; color: rgba(160, 210, 220, 0.4); }

/* ---------------- menu ---------------- */

.overlay {
  position: absolute; inset: 0; z-index: 20; display: flex; align-items: center; justify-content: center;
  background: radial-gradient(ellipse at 50% 45%, rgba(10, 30, 42, 0.55), rgba(2, 5, 9, 0.88) 70%, #020407);
  overflow: hidden;
}
.overlay.hidden { display: none; }

#menu { align-items: center; justify-content: flex-start; padding-left: clamp(28px, 8vw, 140px); }
.menu-bg-grid {
  position: absolute; inset: 0; pointer-events: none; opacity: 0.5;
  background-image:
    linear-gradient(rgba(95, 246, 255, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(95, 246, 255, 0.055) 1px, transparent 1px);
  background-size: 58px 58px;
  mask-image: radial-gradient(ellipse at 38% 50%, #000 0%, transparent 68%);
  -webkit-mask-image: radial-gradient(ellipse at 38% 50%, #000 0%, transparent 68%);
  transform: perspective(500px) rotateX(0deg);
}
.menu-bg-grid::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(90deg, transparent 48%, rgba(255, 46, 136, 0.12) 49.7%, transparent 50.2%);
}
.menu-wrap { position: relative; z-index: 2; width: min(620px, 88vw); padding: 20px 0; }
.menu-eyebrow { display: flex; align-items: center; gap: 12px; font-size: 8.5px; letter-spacing: 0.44em; color: var(--amber); margin-bottom: 18px; }
.menu-eyebrow .line { height: 1px; width: 34px; background: linear-gradient(90deg, transparent, var(--amber)); }
.menu-eyebrow .line:last-child { background: linear-gradient(90deg, var(--amber), transparent); }

.title {
  margin: 0; line-height: 0.82; font-size: clamp(74px, 11vw, 150px); font-weight: 800; letter-spacing: 0.015em;
  color: #f0feff;
  text-shadow: 0 0 60px rgba(65, 235, 255, 0.22), 0 0 4px rgba(255,255,255,0.3);
  -webkit-text-stroke: 1px rgba(140, 245, 255, 0.18);
}
.title span { color: transparent; -webkit-text-stroke: 1.5px var(--cyan); text-shadow: 0 0 46px rgba(95, 246, 255, 0.4); }
.title-sub { margin-top: 12px; font-size: 12px; letter-spacing: 0.5em; color: var(--cyan); }
.title-sub em { color: rgba(255,255,255,0.3); font-style: normal; }
.menu-copy { max-width: 410px; margin: 26px 0 34px; font-size: 12px; line-height: 1.75; letter-spacing: 0.12em; color: rgba(190, 226, 232, 0.68); text-transform: uppercase; }

.cta {
  position: relative; background: none; border: 1px solid rgba(95, 246, 255, 0.5); color: #eaffff; cursor: pointer;
  padding: 13px 46px 14px; font-family: var(--font); text-transform: uppercase; letter-spacing: 0.3em;
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
  background: linear-gradient(120deg, rgba(35, 140, 160, 0.22), rgba(10, 24, 32, 0.6));
  transition: background 0.2s, box-shadow 0.2s, transform 0.1s;
  box-shadow: inset 0 0 30px rgba(95, 246, 255, 0.06), 0 0 30px rgba(20, 130, 150, 0.1);
  pointer-events: auto;
}
.cta::before { content: ""; position: absolute; inset: 3px; border: 1px solid rgba(95, 246, 255, 0.12); clip-path: inherit; pointer-events: none; }
.cta:hover { background: linear-gradient(120deg, rgba(50, 200, 220, 0.34), rgba(16, 44, 54, 0.8)); box-shadow: inset 0 0 40px rgba(95, 246, 255, 0.13), 0 0 44px rgba(55, 210, 235, 0.24); }
.cta:active { transform: scale(0.985); }
.cta-small { display: block; font-size: 7px; letter-spacing: 0.42em; color: var(--amber); margin-bottom: 3px; }
.cta-main { display: block; font-size: 23px; font-weight: 800; letter-spacing: 0.3em; text-indent: 0.3em; }
.cta.compact { padding: 11px 34px; }
.cta.compact .cta-main { font-size: 17px; }

.controls-grid {
  display: grid; grid-template-columns: repeat(4, auto); gap: 12px 26px; justify-content: start;
  margin-top: 34px; padding-top: 20px; border-top: 1px solid rgba(95, 246, 255, 0.12);
}
.controls-grid div { display: flex; flex-direction: column; gap: 4px; }
.controls-grid kbd {
  font-family: var(--font); font-size: 9px; letter-spacing: 0.14em; color: #c7f7ff;
  border: 1px solid rgba(95, 246, 255, 0.25); padding: 4px 7px; background: rgba(10, 24, 32, 0.45); width: fit-content;
}
.controls-grid span { font-size: 7px; letter-spacing: 0.28em; color: rgba(160, 205, 215, 0.45); }
.menu-foot { display: flex; justify-content: space-between; gap: 20px; margin-top: 26px; font-size: 7px; letter-spacing: 0.24em; color: rgba(140, 190, 200, 0.34); }

/* ---------------- pause / game over ---------------- */

#pause { background: rgba(2, 6, 10, 0.66); backdrop-filter: blur(5px); }
.pause-card { width: min(420px, 84vw); padding: 34px 38px; text-align: center; }
.eyebrow { font-size: 8px; letter-spacing: 0.46em; color: var(--cyan); }
.eyebrow.danger { color: var(--danger); }
.pause-card h2 { margin: 12px 0 24px; font-size: 44px; letter-spacing: 0.18em; font-weight: 800; }
.pause-stats, .over-stats { display: flex; justify-content: center; gap: 26px; margin-bottom: 28px; }
.pause-stats div, .over-stats div { display: flex; flex-direction: column; gap: 4px; }
.pause-stats span, .over-stats span { font-size: 7px; letter-spacing: 0.26em; color: var(--muted); }
.pause-stats b, .over-stats b { font-size: 24px; color: var(--amber); letter-spacing: 0.06em; }
.pause-note { margin-top: 14px; font-size: 7px; letter-spacing: 0.2em; color: rgba(150, 200, 210, 0.4); }

#gameover { background: radial-gradient(ellipse at 50% 45%, rgba(50, 5, 12, 0.42), rgba(2, 4, 8, 0.93) 68%); }
.over-card { width: min(560px, 88vw); text-align: center; padding: 20px; }
.over-card h2 { margin: 14px 0 34px; font-size: clamp(48px, 9vw, 82px); line-height: 0.9; letter-spacing: 0.12em; font-weight: 800; }
.over-card h2 span { color: var(--danger); text-shadow: 0 0 42px rgba(255, 50, 70, 0.35); }
.over-stats { margin-bottom: 40px; gap: 40px; }
.over-stats b { font-size: 34px; }

/* ---------------- loader ---------------- */

#loading { background: #03060a; z-index: 30; transition: opacity 0.6s; }
#loading.done { opacity: 0; pointer-events: none; }
.loader { display: flex; flex-direction: column; align-items: center; gap: 22px; }
.loader-ring {
  width: 74px; height: 74px; border-radius: 50%;
  border: 1px solid rgba(95, 246, 255, 0.12); border-top-color: var(--amber);
  animation: spin 1s linear infinite; box-shadow: 0 0 30px rgba(95, 246, 255, 0.12);
}
@keyframes spin { to { transform: rotate(360deg); } }
.loader-text { font-size: 8.5px; letter-spacing: 0.42em; color: var(--muted); }
.loader-text .dots { animation: dots 1.2s steps(4) infinite; }
@keyframes dots { 0% { opacity: 0.2; } 50% { opacity: 1; } }

/* ---------------- touch ---------------- */

#touch-ui { display: none; position: absolute; inset: 0; z-index: 9; pointer-events: none; }
#look-zone { position: absolute; right: 0; top: 0; width: 55%; height: 100%; pointer-events: auto; touch-action: none; }
#joystick {
  position: absolute; left: max(24px, env(safe-area-inset-left)); bottom: max(120px, calc(env(safe-area-inset-bottom) + 104px));
  width: 112px; height: 112px; border-radius: 50%; pointer-events: auto; touch-action: none;
  background: radial-gradient(circle, rgba(10, 30, 40, 0.35), rgba(4, 12, 18, 0.16));
  border: 1px solid rgba(95, 246, 255, 0.24); box-shadow: inset 0 0 26px rgba(95,246,255,0.05);
}
#joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(150, 255, 255, 0.55), rgba(30, 120, 140, 0.25));
  border: 1px solid rgba(150, 250, 255, 0.5); box-shadow: 0 0 20px rgba(60, 220, 240, 0.25);
}
#touch-buttons { position: absolute; right: max(20px, env(safe-area-inset-right)); bottom: max(108px, calc(env(safe-area-inset-bottom) + 94px)); width: 174px; height: 190px; pointer-events: none; }
.touch-btn {
  position: absolute; pointer-events: auto; touch-action: none; font-family: var(--font); color: var(--text);
  border: 1px solid rgba(95, 246, 255, 0.3); background: rgba(8, 22, 30, 0.45); backdrop-filter: blur(3px);
  border-radius: 50%; display: flex; align-items: center; justify-content: center; letter-spacing: 0.12em;
}
.touch-btn.small { width: 52px; height: 52px; font-size: 7px; }
.touch-btn.fire { right: 0; bottom: 0; width: 86px; height: 86px; border-color: rgba(255, 150, 60, 0.5); background: radial-gradient(circle, rgba(255, 120, 40, 0.18), rgba(40, 14, 4, 0.4)); }
.touch-btn.fire span { width: 26px; height: 26px; border-radius: 50%; border: 2px solid var(--amber); box-shadow: 0 0 18px rgba(255, 160, 60, 0.4); }
.touch-btn.fire:active { background: radial-gradient(circle, rgba(255, 160, 60, 0.4), rgba(60, 20, 4, 0.6)); }
#btn-reload { left: 0; bottom: 0; }
#btn-jump { right: 94px; bottom: 8px; }
#btn-aim { right: 8px; bottom: 94px; }

#rotate-hint { display: none; }

/* ---------------- responsive ---------------- */

@media (max-width: 880px) {
  #objective { display: none; }
  #hud { padding: max(12px, env(safe-area-inset-top)) 14px max(12px, env(safe-area-inset-bottom)); }
  .brand-block { min-width: 0; }
  .brand { font-size: 15px; }
  .brand-sub { display: none; }
  .top-right { min-width: 0; }
  #radar-wrap { width: 104px; height: 104px; }
  .vitals { width: 46vw; padding: 9px 12px 8px; }
  .weapon-block { min-width: 0; }
  #ammo { font-size: 38px; }
  .controls-grid { display: none; }
  .menu-copy { display: none; }
  #menu { padding-left: 8vw; justify-content: center; }
  .menu-wrap { width: 84vw; }
  .menu-foot { display: none; }
}

@media (hover: none), (pointer: coarse) {
  #touch-ui { display: block; }
  #hud-bottom { padding-bottom: 150px; }
  .vitals { width: 40vw; }
  .weapon-block { align-self: flex-end; }
  .weapon-hint { display: none; }
  #kill-feed { top: 22%; }
  .brand-block { display: none; }
  #radar-wrap { width: 96px; height: 96px; }
}

@media (max-height: 540px) {
  #wave-banner { top: 62px; }
  #wave-title { font-size: 26px; }
  .vitals { padding: 7px 10px; }
  .weapon-hint { display: none; }
  #hud-bottom { padding-bottom: 110px; }
  #joystick { width: 92px; height: 92px; bottom: 80px; }
  #touch-buttons { transform: scale(0.86); transform-origin: bottom right; bottom: 74px; }
}

@media (orientation: portrait) and (max-width: 480px) {
  #rotate-hint { display: flex; position: absolute; z-index: 8; right: 14px; top: 14px; align-items: center; gap: 6px; font-size: 6px; letter-spacing: 0.2em; color: rgba(150, 220, 230, 0.5); }
  .rotate-icon { width: 12px; height: 18px; border: 1px solid rgba(95, 246, 255, 0.4); border-radius: 3px; }
}

