input.content:
import * as THREE from 'three';

/* ------------------------------------------------------------------ *
 *  Procedural texture atelier — everything in Nightfall is generated
 *  at runtime so the game ships with zero external art dependencies.
 * ------------------------------------------------------------------ */

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function canvas(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return c;
}

function tex(c, { srgb = true, repeat = null, anisotropy = 8, wrap = true } = {}) {
  const t = new THREE.CanvasTexture(c);
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  if (wrap) { t.wrapS = THREE.RepeatWrapping; t.wrapT = THREE.RepeatWrapping; }
  if (repeat) t.repeat.set(repeat[0], repeat[1]);
  t.anisotropy = anisotropy;
  t.needsUpdate = true;
  return t;
}

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

function addNoise(ctx, w, h, rnd, amount, alpha = 0.5, size = 1) {
  for (let i = 0; i < amount; i++) {
    const g = Math.floor(rnd() * 255);
    ctx.fillStyle = `rgba(${g},${g},${g},${alpha * rnd()})`;
    ctx.fillRect(rnd() * w, rnd() * h, size * (1 + rnd() * 3), size * (1 + rnd() * 3));
  }
}

/* ---------------------------- particles --------------------------- */

export function createGlowTexture(color = '#8ff7ff', soft = 0.18) {
  const c = canvas(128, 128), ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, color);
  g.addColorStop(soft, color);
  g.addColorStop(0.45, hexA(color, 0.32));
  g.addColorStop(1, hexA(color, 0));
  ctx.fillStyle = g; ctx.fillRect(0, 0, 128, 128);
  return tex(c, { wrap: false });
}

function hexA(hex, a) {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map(x => x + x).join('') : h, 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
}

export function createSparkTexture() {
  const c = canvas(64, 64), ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, '#ffffff');
  g.addColorStop(0.18, '#fff3c4');
  g.addColorStop(0.45, 'rgba(255,150,40,0.6)');
  g.addColorStop(1, 'rgba(255,80,0,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 64, 64);
  return tex(c, { wrap: false });
}

export function createSmokeTexture() {
  const c = canvas(128, 128), ctx = c.getContext('2d');
  const rnd = mulberry32(99);
  for (let i = 0; i < 26; i++) {
    const x = 40 + rnd() * 48, y = 40 + rnd() * 48, r = 10 + rnd() * 26;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(200,220,225,${0.06 + rnd() * 0.05})`);
    g.addColorStop(1, 'rgba(180,200,210,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
  }
  return tex(c, { wrap: false });
}

export function createRainTexture() {
  const c = canvas(16, 128), ctx = c.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, 128);
  g.addColorStop(0, 'rgba(190,245,255,0)');
  g.addColorStop(0.35, 'rgba(190,245,255,0.22)');
  g.addColorStop(0.8, 'rgba(220,255,255,0.75)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(6, 0, 4, 128);
  return tex(c, { wrap: false });
}

export function createMuzzleTexture() {
  const c = canvas(256, 256), ctx = c.getContext('2d');
  ctx.translate(128, 128);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 120);
  g.addColorStop(0, 'rgba(255,255,240,1)');
  g.addColorStop(0.12, 'rgba(255,225,150,0.98)');
  g.addColorStop(0.34, 'rgba(255,140,40,0.5)');
  g.addColorStop(1, 'rgba(255,80,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, 120, 0, 7); ctx.fill();
  // star flare
  const rnd = mulberry32(4);
  for (let i = 0; i < 7; i++) {
    ctx.save();
    ctx.rotate((i / 7) * Math.PI * 2 + rnd() * 0.3);
    const gr = ctx.createLinearGradient(0, 0, 120, 0);
    gr.addColorStop(0, 'rgba(255,245,210,0.9)');
    gr.addColorStop(1, 'rgba(255,140,20,0)');
    ctx.fillStyle = gr;
    ctx.beginPath(); ctx.moveTo(0, -3); ctx.lineTo(120, 0); ctx.lineTo(0, 3); ctx.fill();
    ctx.restore();
  }
  return tex(c, { wrap: false });
}

export function createRingTexture() {
  const c = canvas(256, 256), ctx = c.getContext('2d');
  ctx.translate(128, 128);
  for (let i = 0; i < 3; i++) {
    ctx.beginPath(); ctx.arc(0, 0, 70 + i * 22, 0, 7);
    ctx.strokeStyle = `rgba(150,255,255,${0.7 - i * 0.2})`;
    ctx.lineWidth = 4 - i; ctx.stroke();
  }
  ctx.beginPath(); ctx.arc(0, 0, 100, 0, 7); ctx.strokeStyle = 'rgba(120,200,255,0.2)'; ctx.lineWidth = 12; ctx.stroke();
  return tex(c, { wrap: false });
}

export function createFlareTexture() {
  const c = canvas(256, 256), ctx = c.getContext('2d');
  ctx.translate(128, 128);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 64);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.1, 'rgba(210,250,255,0.9)');
  g.addColorStop(0.4, 'rgba(80,200,255,0.28)');
  g.addColorStop(1, 'rgba(20,80,140,0)');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, 128, 0, 7); ctx.fill();
  const grd = ctx.createLinearGradient(-128, 0, 128, 0);
  grd.addColorStop(0, 'rgba(120,220,255,0)');
  grd.addColorStop(0.5, 'rgba(220,255,255,0.45)');
  grd.addColorStop(1, 'rgba(120,220,255,0)');
  ctx.fillStyle = grd; ctx.fillRect(-128, -2, 256, 4);
  return tex(c, { wrap: false });
}

/* ---------------------------- surfaces ---------------------------- */

export function createConcreteTexture(repeat = [6, 6]) {
  const w = 512, h = 512;
  const c = canvas(w, h), ctx = c.getContext('2d');
  const rnd = mulberry32(1337);
  ctx.fillStyle = '#20262b'; ctx.fillRect(0, 0, w, h);
  for (let i = 0; i < 9000; i++) {
    const g = 20 + Math.floor(rnd() * 55);
    ctx.fillStyle = `rgba(${g},${g + 4},${g + 6},${0.15 + rnd() * 0.35})`;
    ctx.fillRect(rnd() * w, rnd() * h, 1 + rnd() * 3, 1 + rnd() * 3);
  }
  // slabs / cracks
  ctx.strokeStyle = 'rgba(8,11,13,0.55)'; ctx.lineWidth = 2;
  for (let i = 0; i < 9; i++) {
    let x = rnd() * w, y = rnd() * h;
    ctx.beginPath(); ctx.moveTo(x, y);
    for (let j = 0; j < 5; j++) { x += (rnd() - 0.5) * 80; y += (rnd() - 0.5) * 80; ctx.lineTo(x, y); }
    ctx.stroke();
  }
  // stains
  for (let i = 0; i < 26; i++) {
    const x = rnd() * w, y = rnd() * h, r = 14 + rnd() * 70;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(8,12,14,${0.1 + rnd() * 0.18})`);
    g.addColorStop(1, 'rgba(8,12,14,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
  }
  // expansion joints
  ctx.strokeStyle = 'rgba(10,14,16,0.75)'; ctx.lineWidth = 4;
  for (let i = 1; i < 4; i++) {
    ctx.beginPath(); ctx.moveTo(i * w / 4, 0); ctx.lineTo(i * w / 4, h); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, i * h / 4); ctx.lineTo(w, i * h / 4); ctx.stroke();
  }
  // faint hazard scuffs
  ctx.strokeStyle = 'rgba(150,120,40,0.12)';
  for (let i = 0; i < 6; i++) {
    ctx.beginPath(); ctx.arc(rnd() * w, rnd() * h, 20 + rnd() * 90, rnd() * 7, rnd() * 7 + 1); ctx.stroke();
  }
  return tex(c, { repeat });
}

export function createConcreteRoughness(repeat = [6, 6]) {
  const w = 256, h = 256, c = canvas(w, h), ctx = c.getContext('2d');
  const rnd = mulberry32(2222);
  ctx.fillStyle = '#8a8a8a'; ctx.fillRect(0, 0, w, h);
  for (let i = 0; i < 3000; i++) {
    const g = 70 + Math.floor(rnd() * 120);
    ctx.fillStyle = `rgb(${g},${g},${g})`;
    ctx.fillRect(rnd() * w, rnd() * h, 2 + rnd() * 6, 2 + rnd() * 6);
  }
  // glossier puddle patches -> dark roughness
  for (let i = 0; i < 14; i++) {
    const x = rnd() * w, y = rnd() * h, r = 20 + rnd() * 55;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(18,18,18,0.9)');
    g.addColorStop(1, 'rgba(18,18,18,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
  }
  return tex(c, { repeat, srgb: false });
}

export function createMetalTexture(repeat = [2, 2]) {
  const w = 256, h = 256, c = canvas(w, h), ctx = c.getContext('2d');
  const rnd = mulberry32(707);
  ctx.fillStyle = '#5b646c'; ctx.fillRect(0, 0, w, h);
  for (let i = 0; i < 2400; i++) {
    const g = 60 + Math.floor(rnd() * 70);
    ctx.fillStyle = `rgba(${g},${g + 3},${g + 6},0.35)`;
    ctx.fillRect(0, rnd() * h, w, 1);
  }
  addNoise(ctx, w, h, rnd, 5000, 0.25, 1);
  // rivets + panel lines
  ctx.strokeStyle = 'rgba(20,24,28,0.6)'; ctx.lineWidth = 2;
  for (let i = 1; i < 4; i++) {
    ctx.beginPath(); ctx.moveTo(0, i * h / 4); ctx.lineTo(w, i * h / 4); ctx.stroke();
  }
  for (let i = 0; i < 40; i++) {
    const x = (i % 8) * 32 + 16, y = Math.floor(i / 8) * 51 + 20;
    const g = ctx.createRadialGradient(x - 2, y - 2, 0, x, y, 5);
    g.addColorStop(0, '#a8b2ba'); g.addColorStop(1, '#3a4248');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, 4, 0, 7); ctx.fill();
  }
  return tex(c, { repeat });
}

/* ---------------------------- city --------------------------------- */

const BUILDING_PALETTES = [
  { wall: '#0d141c', rim: '#0a1016', warm: '#ffb45a', cool: '#5fd8ff', accent: '#ff2e88' },
  { wall: '#151218', rim: '#0b090d', warm: '#ffc46e', cool: '#4cd8d2', accent: '#9c6cff' },
  { wall: '#0b1519', rim: '#070e12', warm: '#ffd08a', cool: '#55f2ff', accent: '#27ffc3' },
  { wall: '#17141a', rim: '#0e0b10', warm: '#ffab52', cool: '#69c0ff', accent: '#ff3a6a' },
  { wall: '#0c1117', rim: '#080c11', warm: '#ffcf7a', cool: '#8de8ff', accent: '#ff6bd6' },
  { wall: '#10161b', rim: '#090e12', warm: '#ffb95f', cool: '#39e0ff', accent: '#ff8a2a' },
];

export function createBuildingTextures(variant = 0, seed = 1) {
  const pal = BUILDING_PALETTES[variant % BUILDING_PALETTES.length];
  const w = 256, h = 512;
  const c = canvas(w, h), ctx = c.getContext('2d');
  const e = canvas(w, h), ectx = e.getContext('2d');
  const rnd = mulberry32(seed * 7717 + 13);
  ctx.fillStyle = pal.wall; ctx.fillRect(0, 0, w, h);
  ectx.fillStyle = '#000'; ectx.fillRect(0, 0, w, h);

  // façade vertical banding
  for (let i = 0; i < 10; i++) {
    ctx.fillStyle = i % 2 ? 'rgba(255,255,255,0.018)' : 'rgba(0,0,0,0.14)';
    ctx.fillRect(i * w / 10, 0, w / 10, h);
  }

  // window grid
  const cols = 7, rows = 26;
  const padX = 10, padY = 12;
  const cw = (w - padX * 2) / cols;
  const ch = (h - padY * 2) / rows;
  for (let r = 0; r < rows; r++) {
    for (let col = 0; col < cols; col++) {
      const x = padX + col * cw + 4;
      const y = padY + r * ch + 4;
      const ww = cw - 8, hh = ch - 7;
      const lit = rnd();
      ctx.fillStyle = '#0a1117';
      ctx.fillRect(x, y, ww, hh);
      if (lit > 0.55) {
        const color = lit > 0.93 ? pal.accent : (rnd() > 0.48 ? pal.warm : pal.cool);
        const glow = lit > 0.93 ? 1 : 0.45 + rnd() * 0.5;
        ctx.fillStyle = hexA(color, 0.12);
        ctx.fillRect(x - 1, y - 1, ww + 2, hh + 2);
        ectx.fillStyle = hexA(color, glow * 0.9);
        ectx.fillRect(x, y, ww, hh);
        // interior silhouettes
        if (rnd() > 0.72) {
          ectx.fillStyle = 'rgba(0,0,0,0.45)';
          ectx.fillRect(x + ww * 0.2, y + hh * 0.35, ww * 0.55, hh * 0.65);
        }
      } else if (lit > 0.42) {
        ectx.fillStyle = hexA(pal.cool, 0.06 + rnd() * 0.08);
        ectx.fillRect(x, y, ww, hh);
      }
    }
    // floor slab
    ctx.fillStyle = 'rgba(5,8,11,0.35)';
    ctx.fillRect(0, padY + r * ch, w, 2);
  }

  // neon rim strips
  ctx.fillStyle = pal.accent;
  ctx.fillRect(2, 0, 4, h);
  ectx.fillStyle = pal.accent;
  ectx.fillRect(2, 0, 4, h);
  if (rnd() > 0.4) {
    ctx.fillStyle = pal.cool; ctx.fillRect(w - 6, 0, 3, h);
    ectx.fillStyle = pal.cool; ectx.fillRect(w - 6, 0, 3, h);
  }

  // vertical rooftop crown
  for (let i = 0; i < 8; i++) {
    ctx.fillStyle = 'rgba(0,0,0,0.45)';
    ctx.fillRect(0, i * 4, w, 2);
  }

  return {
    map: tex(c, { repeat: [1, 1] }),
    emissive: tex(e, { repeat: [1, 1] }),
  };
}

export function createBuildingSideTextures(variant = 0, seed = 1) {
  return createBuildingTextures(variant, seed);
}

export function createNeonSignTexture(text, color = '#ff2e88', { vertical = false, sub = '' } = {}) {
  const w = vertical ? 128 : 512;
  const h = vertical ? 512 : 128;
  const c = canvas(w, h), ctx = c.getContext('2d');
  ctx.clearRect(0, 0, w, h);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const font = vertical ? 76 : 72;
  ctx.font = `900 ${font}px "WenQuanYi Zen Hei", "Noto Sans CJK JP", "Trebuchet MS", sans-serif`;

  const draw = (blur, alpha, fill) => {
    ctx.save();
    ctx.shadowColor = color;
    ctx.shadowBlur = blur;
    ctx.fillStyle = fill;
    ctx.globalAlpha = alpha;
    if (vertical) {
      const chars = [...text];
      const step = h / (chars.length + 0.4);
      chars.forEach((ch, i) => ctx.fillText(ch, w / 2, step * (i + 0.75)));
    } else {
      ctx.fillText(text, w / 2, h * 0.44);
      if (sub) {
        ctx.font = '600 18px "Trebuchet MS", sans-serif';
        ctx.letterSpacing = '6px';
        ctx.fillText(sub, w / 2, h * 0.78);
      }
    }
    ctx.restore();
  };
  draw(38, 0.85, color);
  draw(16, 0.9, color);
  draw(4, 1, '#ffffff');
  // frame
  ctx.strokeStyle = hexA(color, 0.55); ctx.lineWidth = 3;
  ctx.strokeRect(5, 5, w - 10, h - 10);
  ctx.strokeStyle = hexA(color, 0.2); ctx.lineWidth = 1;
  ctx.strokeRect(12, 12, w - 24, h - 24);
  return tex(c, { wrap: false });
}

export function createBillboardTexture(variant = 0) {
  const w = 512, h = 512, c = canvas(w, h), ctx = c.getContext('2d');
  const rnd = mulberry32(variant * 4241 + 7);
  const palettes = [
    ['#04121b', '#ff2e88', '#5ff6ff', 'HALO'],
    ['#120a1c', '#ffb43c', '#ff2e88', 'NEO'],
    ['#04161a', '#27ffc3', '#5ff6ff', '羽'],
    ['#160813', '#8d6bff', '#ff8a2a', 'SYNTH'],
    ['#081018', '#5ff6ff', '#ff2e88', '夜'],
    ['#160d06', '#ff7a1a', '#ffd08a', 'AXIOM'],
  ];
  const p = palettes[variant % palettes.length];
  const g = ctx.createLinearGradient(0, 0, w, h);
  g.addColorStop(0, p[0]); g.addColorStop(0.55, p[0]); g.addColorStop(1, '#020407');
  ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);

  // soft light wash
  const glow = ctx.createRadialGradient(w * 0.5, h * 0.45, 10, w * 0.5, h * 0.45, w * 0.7);
  glow.addColorStop(0, hexA(p[1], 0.36)); glow.addColorStop(0.5, hexA(p[2], 0.1)); glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = glow; ctx.fillRect(0, 0, w, h);

  // decorative orbit rings / grids
  ctx.save();
  ctx.translate(w / 2, h / 2);
  ctx.strokeStyle = hexA(p[2], 0.3); ctx.lineWidth = 2;
  for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.arc(0, 0, 60 + i * 45, 0, 7); ctx.stroke(); }
  for (let i = 0; i < 12; i++) {
    ctx.rotate(Math.PI / 6);
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, -200); ctx.strokeStyle = hexA(p[2], 0.08); ctx.stroke();
  }
  ctx.restore();

  // big type
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = '900 146px "WenQuanYi Zen Hei", "Trebuchet MS", sans-serif';
  ctx.shadowColor = p[1]; ctx.shadowBlur = 44; ctx.fillStyle = p[1];
  ctx.fillText(p[3], w / 2, h * 0.5);
  ctx.shadowBlur = 10; ctx.fillStyle = '#fff8ee';
  ctx.globalAlpha = 0.82; ctx.fillText(p[3], w / 2, h * 0.5); ctx.globalAlpha = 1;

  // bars & data
  ctx.shadowBlur = 0;
  ctx.fillStyle = hexA(p[2], 0.7);
  for (let i = 0; i < 28; i++) {
    const bw = 4 + rnd() * 16;
    ctx.fillRect(24, 24 + i * 12, bw, 4);
  }
  ctx.font = '600 13px "Trebuchet MS", sans-serif';
  ctx.fillStyle = hexA(p[2], 0.8); ctx.textAlign = 'right';
  ctx.fillText('SECTOR 07 / 2094', w - 24, h - 34);
  ctx.textAlign = 'left';
  ctx.fillText('◢ SIGNAL LIVE', 24, h - 34);

  // scanlines
  ctx.fillStyle = 'rgba(0,0,0,0.16)';
  for (let y = 0; y < h; y += 4) ctx.fillRect(0, y, w, 1);
  // border
  ctx.strokeStyle = hexA(p[1], 0.6); ctx.lineWidth = 4; ctx.strokeRect(6, 6, w - 12, h - 12);
  return tex(c, { wrap: false });
}

export function createHoloTexture(kind = 0) {
  const w = 512, h = 512, c = canvas(w, h), ctx = c.getContext('2d');
  ctx.clearRect(0, 0, w, h);
  const color = kind === 0 ? '#5ff6ff' : kind === 1 ? '#ff6bd6' : '#ffc46e';
  ctx.strokeStyle = color; ctx.fillStyle = color;
  ctx.shadowColor = color; ctx.shadowBlur = 16;
  ctx.lineWidth = 2;
  ctx.translate(w / 2, h / 2);

  if (kind === 0) {
    // wireframe cyber koi
    ctx.beginPath();
    ctx.moveTo(-160, 10);
    ctx.bezierCurveTo(-80, -100, 80, -120, 150, -10);
    ctx.bezierCurveTo(80, 90, -40, 120, -160, 10);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-160, 10); ctx.lineTo(-230, -60); ctx.lineTo(-210, 30); ctx.lineTo(-250, 70); ctx.closePath(); ctx.stroke();
    ctx.beginPath(); ctx.arc(100, -34, 8, 0, 7); ctx.stroke();
    for (let i = -100; i < 130; i += 26) {
      ctx.beginPath(); ctx.moveTo(i, -70 + Math.abs(i) * 0.1); ctx.lineTo(i + 12, 70 - Math.abs(i) * 0.1); ctx.stroke();
    }
  } else if (kind === 1) {
    // abstract female silhouette / idol hologram
    ctx.beginPath(); ctx.arc(0, -150, 46, 0, 7); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-22, -108); ctx.lineTo(-70, -20); ctx.lineTo(-40, 130); ctx.lineTo(40, 130); ctx.lineTo(70, -20); ctx.lineTo(22, -108);
    ctx.stroke();
    for (let y = -60; y < 120; y += 16) {
      ctx.beginPath(); ctx.moveTo(-90, y); ctx.lineTo(90, y); ctx.strokeStyle = hexA(color, 0.16); ctx.stroke();
    }
    ctx.strokeStyle = color;
    ctx.beginPath(); ctx.arc(0, -150, 60, 0, 7); ctx.strokeStyle = hexA(color, 0.35); ctx.stroke();
  } else {
    // lotus / reactor sigil
    for (let i = 0; i < 8; i++) {
      ctx.save(); ctx.rotate(i * Math.PI / 4);
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(-50, -110, 0, -200);
      ctx.quadraticCurveTo(50, -110, 0, 0);
      ctx.stroke(); ctx.restore();
    }
    ctx.beginPath(); ctx.arc(0, 0, 36, 0, 7); ctx.stroke();
  }
  // scanline bands
  ctx.globalCompositeOperation = 'destination-out';
  for (let y = -h / 2; y < h / 2; y += 5) {
    ctx.fillStyle = `rgba(0,0,0,${0.25 + 0.2 * Math.sin(y)})`;
    ctx.fillRect(-w / 2, y, w, 2);
  }
  return tex(c, { wrap: false });
}

export function createArenaLogoTexture() {
  const w = 512, h = 512, c = canvas(w, h), ctx = c.getContext('2d');
  ctx.clearRect(0, 0, w, h);
  ctx.translate(256, 256);
  ctx.strokeStyle = 'rgba(255,180,60,0.8)'; ctx.fillStyle = 'rgba(255,180,60,0.6)';
  ctx.shadowColor = '#ffb43c'; ctx.shadowBlur = 14; ctx.lineWidth = 5;
  // hex
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2 - Math.PI / 2;
    const x = Math.cos(a) * 170, y = Math.sin(a) * 170;
    i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
  }
  ctx.closePath(); ctx.stroke();
  // wings
  for (const s of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(s * 40, -20); ctx.lineTo(s * 200, -70); ctx.lineTo(s * 160, -4); ctx.lineTo(s * 210, 40); ctx.lineTo(s * 60, 34);
    ctx.stroke();
  }
  ctx.font = '900 92px "Trebuchet MS", sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('NF', 0, -8);
  ctx.font = '700 26px "Trebuchet MS", sans-serif';
  ctx.fillText('SECTOR 07', 0, 70);
  ctx.fillStyle = 'rgba(255,180,60,0.35)';
  for (let i = 0; i < 24; i++) ctx.fillRect(-230 + i * 20, 120, 10, 3);
  return tex(c, { wrap: false });
}

export function createHazardTexture(repeat = [4, 1]) {
  const w = 256, h = 64, c = canvas(w, h), ctx = c.getContext('2d');
  ctx.fillStyle = '#12161a'; ctx.fillRect(0, 0, w, h);
  ctx.save();
  ctx.beginPath(); ctx.rect(0, 0, w, h); ctx.clip();
  for (let x = -h; x < w + h; x += 42) {
    ctx.fillStyle = '#c98f2e';
    ctx.beginPath(); ctx.moveTo(x, h); ctx.lineTo(x + h, 0); ctx.lineTo(x + h + 20, 0); ctx.lineTo(x + 20, h); ctx.fill();
  }
  ctx.restore();
  addNoise(ctx, w, h, mulberry32(12), 800, 0.2, 1);
  return tex(c, { repeat });
}

export function createPanelTexture() {
  const w = 256, h = 256, c = canvas(w, h), ctx = c.getContext('2d');
  const rnd = mulberry32(551);
  ctx.fillStyle = '#2a3238'; ctx.fillRect(0, 0, w, h);
  for (let i = 0; i < 2200; i++) {
    const g = 30 + rnd() * 40;
    ctx.fillStyle = `rgba(${g},${g + 3},${g + 5},0.5)`;
    ctx.fillRect(rnd() * w, rnd() * h, 1 + rnd() * 4, 1 + rnd() * 4);
  }
  ctx.strokeStyle = 'rgba(10,14,18,0.75)'; ctx.lineWidth = 3;
  for (let i = 0; i < 4; i++) {
    ctx.strokeRect(8 + i * 8, 8 + i * 8, w - 16 - i * 16, h - 16 - i * 16);
  }
  ctx.strokeStyle = 'rgba(255,180,60,0.18)';
  ctx.beginPath(); ctx.moveTo(30, 30); ctx.lineTo(80, 30); ctx.moveTo(30, 30); ctx.lineTo(30, 80); ctx.stroke();
  return tex(c, { repeat: [1, 1] });
}

export function createDecalTexture(kind = 0) {
  const w = 128, h = 128, c = canvas(w, h), ctx = c.getContext('2d');
  ctx.clearRect(0, 0, w, h);
  if (kind === 0) {
    // bullet hole with cracks
    const rnd = mulberry32(31);
    const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 34);
    g.addColorStop(0, 'rgba(2,4,6,0.95)');
    g.addColorStop(0.5, 'rgba(8,10,12,0.8)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(64, 64, 34, 0, 7); ctx.fill();
    ctx.strokeStyle = 'rgba(190,210,220,0.16)'; ctx.lineWidth = 1;
    for (let i = 0; i < 12; i++) {
      const a = rnd() * 7, r = 20 + rnd() * 38;
      ctx.beginPath(); ctx.moveTo(64 + Math.cos(a) * 8, 64 + Math.sin(a) * 8);
      ctx.lineTo(64 + Math.cos(a) * r, 64 + Math.sin(a) * r); ctx.stroke();
    }
  } else {
    // scorch
    const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 60);
    g.addColorStop(0, 'rgba(0,0,0,0.85)');
    g.addColorStop(0.45, 'rgba(12,10,8,0.5)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
  }
  return tex(c, { wrap: false });
}

export function createRainSplashTexture() {
  const c = canvas(128, 128), ctx = c.getContext('2d');
  ctx.translate(64, 64);
  for (let i = 0; i < 2; i++) {
    ctx.beginPath(); ctx.ellipse(0, 0, 52 - i * 18, 18 - i * 6, 0, 0, 7);
    ctx.strokeStyle = `rgba(170,240,255,${0.5 - i * 0.15})`; ctx.lineWidth = 2; ctx.stroke();
  }
  return tex(c, { wrap: false });
}

export function createSteamTexture() {
  const c = canvas(128, 128), ctx = c.getContext('2d');
  const rnd = mulberry32(87);
  for (let i = 0; i < 30; i++) {
    const x = 64 + (rnd() - 0.5) * 46, y = 64 + (rnd() - 0.5) * 46, r = 8 + rnd() * 24;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(190,220,230,${0.05 + rnd() * 0.05})`);
    g.addColorStop(1, 'rgba(150,190,200,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
  }
  return tex(c, { wrap: false });
}

export function createCloudTexture() {
  const w = 512, h = 256, c = canvas(w, h), ctx = c.getContext('2d');
  const rnd = mulberry32(5150);
  for (let i = 0; i < 70; i++) {
    const x = 60 + rnd() * (w - 120), y = 80 + rnd() * (h - 110), r = 20 + rnd() * 70;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(140,175,205,${0.045 + rnd() * 0.05})`);
    g.addColorStop(1, 'rgba(100,140,170,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
  }
  return tex(c, { wrap: false });
}

/* Procedural WebAudio soundscape — no audio assets required. */

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.sfx = null;
    this.music = null;
    this.ready = false;
    this.noise = null;
    this._ambienceStarted = false;
    this._lastStep = 0;
  }

  init() {
    if (this.ready) { this.ctx.resume(); return; }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    const ctx = this.ctx;

    this.master = ctx.createGain();
    this.master.gain.value = 0.72;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.knee.value = 18;
    comp.ratio.value = 4;
    comp.attack.value = 0.004;
    comp.release.value = 0.18;
    this.master.connect(comp).connect(ctx.destination);

    this.sfx = ctx.createGain();
    this.sfx.gain.value = 0.9;
    this.sfx.connect(this.master);

    this.music = ctx.createGain();
    this.music.gain.value = 0.0;
    this.music.connect(this.master);

    // reverb bus
    this.reverb = ctx.createConvolver();
    this.reverb.buffer = this._impulse(2.4, 2.6);
    this.reverbGain = ctx.createGain();
    this.reverbGain.gain.value = 0.28;
    this.reverb.connect(this.reverbGain).connect(this.master);

    this.noise = this._noiseBuffer(2.0);
    this.ready = true;
    this._startAmbience();
  }

  _noiseBuffer(sec) {
    const ctx = this.ctx;
    const buf = ctx.createBuffer(1, Math.floor(ctx.sampleRate * sec), ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < data.length; i++) {
      const w = Math.random() * 2 - 1;
      last = (last + 0.02 * w) / 1.02;
      data[i] = last * 3.5;
    }
    return buf;
  }

  _impulse(sec, decay) {
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * sec);
    const buf = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const d = buf.getChannelData(ch);
      for (let i = 0; i < len; i++) {
        d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, decay);
      }
    }
    return buf;
  }

  _noiseSrc(dur = 1) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    src.loopEnd = this.noise.duration;
    src.start(this.ctx.currentTime, Math.random() * 0.5);
    src.stop(this.ctx.currentTime + dur + 0.1);
    return src;
  }

  _startAmbience() {
    if (this._ambienceStarted) return;
    this._ambienceStarted = true;
    const ctx = this.ctx;

    // rain bed — filtered noise, gently modulated
    const rain = this._noiseSrc(9999);
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 2400; bp.Q.value = 0.35;
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass'; hp.frequency.value = 500;
    const g = ctx.createGain(); g.gain.value = 0.055;
    rain.connect(bp).connect(hp).connect(g).connect(this.master);
    const lfo = ctx.createOscillator(); lfo.frequency.value = 0.07;
    const lfoG = ctx.createGain(); lfoG.gain.value = 0.018;
    lfo.connect(lfoG).connect(g.gain); lfo.start();

    // deep city rumble
    const rumble = this._noiseSrc(9999);
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.frequency.value = 110; lp.Q.value = 0.6;
    const rg = ctx.createGain(); rg.gain.value = 0.14;
    rumble.connect(lp).connect(rg).connect(this.master);

    // sustained dystopian pad
    const padGain = ctx.createGain(); padGain.gain.value = 0.035;
    const padFilter = ctx.createBiquadFilter();
    padFilter.type = 'lowpass'; padFilter.frequency.value = 420; padFilter.Q.value = 4;
    padGain.connect(padFilter).connect(this.music);
    [55, 82.41, 110, 164.81].forEach((f, i) => {
      const o = ctx.createOscillator();
      o.type = i % 2 ? 'sawtooth' : 'triangle';
      o.frequency.value = f;
      o.detune.value = (i - 1.5) * 6;
      const og = ctx.createGain(); og.gain.value = 0.25 / (i + 1);
      o.connect(og).connect(padGain);
      o.start();
      const lf = ctx.createOscillator(); lf.frequency.value = 0.03 + i * 0.011;
      const lfg = ctx.createGain(); lfg.gain.value = 2.5;
      lf.connect(lfg).connect(o.frequency); lf.start();
    });
    this.music.gain.setTargetAtTime(0.3, ctx.currentTime, 4);
  }

  setCombat(on) {
    if (!this.ready) return;
    this.music.gain.setTargetAtTime(on ? 0.42 : 0.28, this.ctx.currentTime, 2);
  }

  _env(node, t0, a, d, peak = 1) {
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(peak, t0 + a);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + a + d);
    node.connect(g);
    return g;
  }

  gunshot() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    // crack
    const src = this._noiseSrc(0.2);
    const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 900;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 9500;
    src.connect(hp).connect(lp);
    const g = this._env(lp, t, 0.003, 0.16, 0.75);
    g.connect(this.sfx); g.connect(this.reverb);

    // body thump
    const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.setValueAtTime(160, t);
    o.frequency.exponentialRampToValueAtTime(44, t + 0.12);
    const og = this._env(o, t, 0.004, 0.16, 0.55);
    og.connect(this.sfx);
    o.start(t); o.stop(t + 0.22);

    // mech clack
    const o2 = ctx.createOscillator(); o2.type = 'square'; o2.frequency.setValueAtTime(680, t);
    o2.frequency.exponentialRampToValueAtTime(180, t + 0.03);
    const g2 = this._env(o2, t, 0.001, 0.035, 0.07);
    g2.connect(this.sfx); o2.start(t); o2.stop(t + 0.06);
  }

  hit(crit = false) {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const o = ctx.createOscillator();
    o.type = 'triangle';
    o.frequency.setValueAtTime(crit ? 1600 : 1150, t);
    o.frequency.exponentialRampToValueAtTime(crit ? 2100 : 1500, t + 0.03);
    const g = this._env(o, t, 0.002, crit ? 0.13 : 0.07, 0.16);
    g.connect(this.sfx); o.start(t); o.stop(t + 0.18);
  }

  kill() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const src = this._noiseSrc(0.4);
    const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 700; bp.Q.value = 1.4;
    src.connect(bp);
    const g = this._env(bp, t, 0.005, 0.35, 0.32);
    g.connect(this.sfx); g.connect(this.reverb);
    const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.setValueAtTime(90, t);
    o.frequency.exponentialRampToValueAtTime(30, t + 0.4);
    const og = this._env(o, t, 0.01, 0.4, 0.45); og.connect(this.sfx);
    o.start(t); o.stop(t + 0.5);
  }

  explosion(big = false) {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const src = this._noiseSrc(1.2);
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass';
    lp.frequency.setValueAtTime(big ? 900 : 1600, t);
    lp.frequency.exponentialRampToValueAtTime(big ? 80 : 180, t + 0.9);
    src.connect(lp);
    const g = this._env(lp, t, 0.006, big ? 1.1 : 0.6, big ? 0.95 : 0.55);
    g.connect(this.sfx); g.connect(this.reverb);
    const o = ctx.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(big ? 80 : 120, t);
    o.frequency.exponentialRampToValueAtTime(20, t + (big ? 0.9 : 0.5));
    const og = this._env(o, t, 0.01, big ? 0.95 : 0.5, big ? 0.8 : 0.5);
    og.connect(this.sfx); o.start(t); o.stop(t + 1.1);
  }

  reload() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    // magazine out
    const click = (at, f, dur, vol) => {
      const o = ctx.createOscillator(); o.type = 'square'; o.frequency.value = f;
      const g = this._env(o, t + at, 0.001, dur, vol);
      g.connect(this.sfx); o.start(t + at); o.stop(t + at + dur + 0.05);
    };
    click(0, 240, 0.05, 0.1);
    click(0.16, 160, 0.07, 0.14);
    click(0.62, 320, 0.04, 0.1);
    click(0.78, 520, 0.03, 0.12);
    const src = this._noiseSrc(0.12);
    const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 2200;
    src.connect(bp);
    const g = this._env(bp, t + 0.78, 0.002, 0.08, 0.08);
    g.connect(this.sfx);
  }

  empty() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const o = ctx.createOscillator(); o.type = 'square'; o.frequency.value = 140;
    const g = this._env(o, t, 0.001, 0.05, 0.09); g.connect(this.sfx);
    o.start(t); o.stop(t + 0.08);
  }

  damage() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const o = ctx.createOscillator(); o.type = 'sawtooth';
    o.frequency.setValueAtTime(220, t); o.frequency.exponentialRampToValueAtTime(60, t + 0.25);
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 800;
    o.connect(lp);
    const g = this._env(lp, t, 0.006, 0.3, 0.3); g.connect(this.sfx); g.connect(this.reverb);
    o.start(t); o.stop(t + 0.4);
  }

  wave() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    [220, 330, 440].forEach((f, i) => {
      const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = f;
      const g = this._env(o, t + i * 0.16, 0.03, 0.5, 0.12);
      g.connect(this.sfx); g.connect(this.reverb);
      o.start(t + i * 0.16); o.stop(t + i * 0.16 + 0.6);
    });
  }

  step(sprint = false) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    if (now - this._lastStep < (sprint ? 0.24 : 0.34)) return;
    this._lastStep = now;
    const ctx = this.ctx, t = now;
    const src = this._noiseSrc(0.1);
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 420;
    src.connect(lp);
    const g = this._env(lp, t, 0.004, 0.09, 0.13);
    g.connect(this.sfx);
  }

  ui() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = 880;
    const g = this._env(o, t, 0.002, 0.08, 0.08); g.connect(this.sfx);
    o.start(t); o.stop(t + 0.12);
  }
}

import * as THREE from 'three';
import {
  mulberry32, createGlowTexture, createSparkTexture, createSmokeTexture, createRainTexture,
  createMuzzleTexture, createRingTexture, createFlareTexture, createConcreteTexture,
  createConcreteRoughness, createMetalTexture, createBuildingTextures, createNeonSignTexture,
  createBillboardTexture, createHoloTexture, createArenaLogoTexture, createHazardTexture,
  createPanelTexture, createDecalTexture, createRainSplashTexture, createSteamTexture,
  createCloudTexture,
} from './textures.js';

const TAU = Math.PI * 2;

/* ================================================================== *
 *  NIGHTFALL — rooftop arena + layered neon metropolis
 * ================================================================== */

export class World {
  constructor(scene, renderer, opts = {}) {
    this.scene = scene;
    this.renderer = renderer;
    this.low = !!opts.low;
    this.rnd = mulberry32(2077);
    this.colliders = [];
    this.spawnPoints = [];
    this.playerBounds = 23.4;
    this.updaters = [];
    this.beacons = [];
    this.cars = [];
    this.drones = [];
    this.lightningTimer = 12 + Math.random() * 20;
    this.flash = 0;
    this.time = 0;

    this.textures = {
      glowCyan: createGlowTexture('#a8fbff', 0.12),
      glowPink: createGlowTexture('#ff78c4', 0.12),
      glowAmber: createGlowTexture('#ffd08a', 0.12),
      glowWhite: createGlowTexture('#ffffff', 0.12),
      spark: createSparkTexture(),
      smoke: createSmokeTexture(),
      rain: createRainTexture(),
      muzzle: createMuzzleTexture(),
      ring: createRingTexture(),
      flare: createFlareTexture(),
      splash: createRainSplashTexture(),
      steam: createSteamTexture(),
      cloud: createCloudTexture(),
    };

    this._buildEnvironmentMap();
    this._buildSky();
    this._buildCity();
    this._buildMaglev();
    this._buildTraffic();
    this._buildArena();
    this._buildAtmosphere();
    this._buildLighting();
    scene.fog = new THREE.FogExp2(0x0a141d, 0.0046);
  }

  /* ---------------------------------------------------------------- */
  /*  environment reflection                                          */
  /* ---------------------------------------------------------------- */

  _buildEnvironmentMap() {
    const env = new THREE.Scene();
    const geo = new THREE.SphereGeometry(60, 32, 16);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      uniforms: {
        top: { value: new THREE.Color(0x06121e) },
        horizon: { value: new THREE.Color(0x2b2540) },
        bottom: { value: new THREE.Color(0x030508) },
      },
      vertexShader: `varying vec3 vP; void main(){ vP = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        uniform vec3 top; uniform vec3 horizon; uniform vec3 bottom; varying vec3 vP;
        void main(){
          float h = vP.y;
          vec3 c = h > 0.0 ? mix(horizon, top, pow(h, 0.55)) : mix(horizon, bottom, pow(-h, 0.4));
          gl_FragColor = vec4(c, 1.0);
        }`,
    });
    env.add(new THREE.Mesh(geo, mat));
    const panelGeo = new THREE.PlaneGeometry(18, 8);
    const colors = [0x5ff6ff, 0xff2e88, 0xffb43c, 0x27ffc3];
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU;
      const m = new THREE.Mesh(panelGeo, new THREE.MeshBasicMaterial({ color: colors[i % 4], side: THREE.DoubleSide }));
      m.position.set(Math.cos(a) * 24, 4 + (i % 3) * 8, Math.sin(a) * 24);
      m.lookAt(0, 4, 0);
      env.add(m);
    }
    const pmrem = new THREE.PMREMGenerator(this.renderer);
    const rt = pmrem.fromScene(env, 0.02);
    this.scene.environment = rt.texture;
    this.scene.environmentIntensity = 0.65;
    pmrem.dispose();
  }

  /* ---------------------------------------------------------------- */
  /*  sky, moon, clouds, stars                                        */
  /* ---------------------------------------------------------------- */

  _buildSky() {
    const geo = new THREE.SphereGeometry(900, 48, 32);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        uTime: { value: 0 },
        uTop: { value: new THREE.Color(0x02050c) },
        uMid: { value: new THREE.Color(0x0b1a2e) },
        uHorizon: { value: new THREE.Color(0x3a1b3d) },
        uGlow: { value: new THREE.Color(0x8c2a4a) },
      },
      vertexShader: `
        varying vec3 vDir;
        void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        uniform float uTime; uniform vec3 uTop, uMid, uHorizon, uGlow;
        varying vec3 vDir;
        float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
        float noise(vec2 p){
          vec2 i = floor(p), f = fract(p); f = f*f*(3.0-2.0*f);
          return mix(mix(hash(i), hash(i+vec2(1,0)), f.x), mix(hash(i+vec2(0,1)), hash(i+vec2(1,1)), f.x), f.y);
        }
        float fbm(vec2 p){
          float v = 0.0, a = 0.5;
          for(int i=0;i<5;i++){ v += a*noise(p); p *= 2.03; a *= 0.5; }
          return v;
        }
        void main(){
          vec3 d = normalize(vDir);
          float h = max(d.y, 0.0);
          vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.28, h));
          col = mix(col, uTop, smoothstep(0.12, 0.85, h));
          // city light pollution bloom near horizon
          float glow = pow(max(0.0, 1.0 - h*2.4), 2.0) * (0.55 + 0.45*noise(vec2(atan(d.z,d.x)*3.0, 2.0)));
          col += uGlow * glow * 0.22;
          // high cloud bands
          vec2 uv = vec2(atan(d.z, d.x) * 1.7 + uTime * 0.004, d.y * 2.2);
          float cl = smoothstep(0.5, 0.85, fbm(uv * 2.4 + fbm(uv * 1.5)));
          col = mix(col, vec3(0.10,0.12,0.18), cl * smoothstep(0.04, 0.5, h) * 0.55);
          // stars
          if (h > 0.12) {
            vec2 sp = d.xz / max(d.y, 0.1);
            float star = step(0.9975, hash(floor(sp * 90.0)));
            col += vec3(0.55,0.7,0.9) * star * smoothstep(0.12, 0.4, h) * 0.55;
          }
          gl_FragColor = vec4(col, 1.0);
        }`,
    });
    this.skyMat = mat;
    this.sky = new THREE.Mesh(geo, mat);
    this.sky.frustumCulled = false;
    this.scene.add(this.sky);

    // moon glow + core
    const moon = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.textures.glowWhite, color: 0xa9d8ff, transparent: true,
      opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
    }));
    moon.scale.set(190, 190, 1);
    moon.position.set(-300, 215, -620);
    this.scene.add(moon);

    const moonCore = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.textures.glowWhite, color: 0xf2fbff, transparent: true,
      opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
    }));
    moonCore.scale.set(44, 44, 1);
    moonCore.position.copy(moon.position);
    this.scene.add(moonCore);

    // high haze clouds
    this.clouds = [];
    for (let i = 0; i < 9; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.textures.cloud, color: i % 3 === 0 ? 0x8b617a : 0x3a5368,
        transparent: true, opacity: 0.26 + this.rnd() * 0.14, depthWrite: false, fog: false,
      }));
      const a = this.rnd() * TAU, r = 320 + this.rnd() * 260;
      s.position.set(Math.cos(a) * r, 80 + this.rnd() * 150, Math.sin(a) * r);
      const sc = 260 + this.rnd() * 260;
      s.scale.set(sc, sc * 0.48, 1);
      s.userData.speed = 0.4 + this.rnd() * 0.7;
      this.clouds.push(s);
      this.scene.add(s);
    }
  }

  /* ---------------------------------------------------------------- */
  /*  layered city                                                    */
  /* ---------------------------------------------------------------- */

  _buildCity() {
    const rnd = this.rnd;
    const variants = 6;
    const materials = [];
    for (let v = 0; v < variants; v++) {
      const maps = createBuildingTextures(v, 40 + v);
      materials.push(new THREE.MeshStandardMaterial({
        map: maps.map,
        emissiveMap: maps.emissive,
        emissive: 0xffffff,
        emissiveIntensity: 1.45,
        roughness: 0.78,
        metalness: 0.22,
        envMapIntensity: 0.55,
      }));
    }

    this.buildings = [];
    const rings = [
      { count: 26, r0: 58, r1: 112, base: -34, h0: 34, h1: 82, w0: 10, w1: 22, jitter: 0.9 },
      { count: 30, r0: 128, r1: 215, base: -52, h0: 55, h1: 132, w0: 12, w1: 30, jitter: 1.0 },
      { count: 30, r0: 245, r1: 400, base: -72, h0: 80, h1: 230, w0: 16, w1: 42, jitter: 1.1 },
    ];

    for (const ring of rings) {
      for (let i = 0; i < ring.count; i++) {
        const a = (i / ring.count) * TAU + (rnd() - 0.5) * ((TAU / ring.count) * 0.6);
        const r = ring.r0 + rnd() * (ring.r1 - ring.r0);
        const w = ring.w0 + rnd() * (ring.w1 - ring.w0);
        const d = ring.w0 + rnd() * (ring.w1 - ring.w0);
        const h = ring.h0 + rnd() * (ring.h1 - ring.h0);
        this.buildings.push({
          x: Math.cos(a) * r,
          z: Math.sin(a) * r,
          w, d, h,
          base: ring.base + rnd() * 10,
          rot: (rnd() - 0.5) * 0.35,
          variant: Math.floor(rnd() * variants),
          ring: rings.indexOf(ring),
          angle: a,
          radius: r,
        });
      }
    }

    // Instance the building shells per material
    const dummy = new THREE.Object3D();
    const box = new THREE.BoxGeometry(1, 1, 1);
    const byMat = Array.from({ length: variants }, () => []);
    for (const b of this.buildings) byMat[b.variant].push(b);

    byMat.forEach((list, vi) => {
      const inst = new THREE.InstancedMesh(box, materials[vi], list.length);
      inst.castShadow = false;
      inst.receiveShadow = false;
      list.forEach((b, i) => {
        dummy.position.set(b.x, b.base + b.h / 2, b.z);
        dummy.rotation.set(0, b.rot, 0);
        dummy.scale.set(b.w, b.h, b.d);
        dummy.updateMatrix();
        inst.setMatrixAt(i, dummy.matrix);
      });
      inst.instanceMatrix.needsUpdate = true;
      this.scene.add(inst);
    });

    // Rooftop clutter (instanced dark boxes)
    const roofMat = new THREE.MeshStandardMaterial({ color: 0x141b21, roughness: 0.7, metalness: 0.55, envMapIntensity: 0.7 });
    const roofItems = [];
    const antennaItems = [];
    const antennaMat = new THREE.MeshStandardMaterial({ color: 0x2b343c, roughness: 0.5, metalness: 0.8 });
    const beaconPositions = [];

    for (const b of this.buildings) {
      const top = b.base + b.h;
      const n = 1 + Math.floor(rnd() * 3);
      for (let i = 0; i < n; i++) {
        const w = b.w * (0.12 + rnd() * 0.28);
        const d = b.d * (0.12 + rnd() * 0.28);
        const h = 1 + rnd() * 4.5;
        roofItems.push({
          x: b.x + (rnd() - 0.5) * b.w * 0.6,
          z: b.z + (rnd() - 0.5) * b.d * 0.6,
          y: top + h / 2,
          w, h, d,
        });
      }
      if (rnd() > 0.32) {
        const ah = 4 + rnd() * 16;
        antennaItems.push({ x: b.x + (rnd() - 0.5) * b.w * 0.3, z: b.z + (rnd() - 0.5) * b.d * 0.3, y: top + ah / 2, h: ah });
        beaconPositions.push(new THREE.Vector3(b.x, top + ah + 0.3, b.z));
      }
      if (b.ring === 0 && rnd() > 0.6) {
        beaconPositions.push(new THREE.Vector3(b.x, top + 0.5, b.z));
      }
    }

    const makeInstances = (items, geo, mat) => {
      const inst = new THREE.InstancedMesh(geo, mat, items.length);
      items.forEach((it, i) => {
        dummy.position.set(it.x, it.y, it.z);
        dummy.rotation.set(0, it.rot || 0, 0);
        dummy.scale.set(it.w ?? 1, it.h ?? 1, it.d ?? 1);
        dummy.updateMatrix();
        inst.setMatrixAt(i, dummy.matrix);
      });
      inst.instanceMatrix.needsUpdate = true;
      this.scene.add(inst);
      return inst;
    };
    makeInstances(roofItems, new THREE.BoxGeometry(1, 1, 1), roofMat);
    makeInstances(antennaItems, new THREE.CylinderGeometry(0.18, 0.55, 1, 5), antennaMat);

    // Neon edge strips instanced by colour
    const stripColors = [0x5ff6ff, 0xff2e88, 0xffb43c, 0x27ffc3];
    const stripGroups = [[], [], [], []];
    for (const b of this.buildings) {
      if (rnd() > 0.72) continue;
      const ci = Math.floor(rnd() * 4);
      const top = b.base + b.h;
      stripGroups[ci].push({ x: b.x, z: b.z, y: (b.base + top) / 2, w: b.w * 1.012, h: b.h * 0.92, d: 0.16, rot: b.rot, edge: rnd() > 0.5 ? 1 : -1 });
    }
    stripGroups.forEach((list, i) => {
      if (!list.length) return;
      const mat = new THREE.MeshBasicMaterial({ color: stripColors[i], toneMapped: false });
      const geo = new THREE.BoxGeometry(1, 1, 0.2);
      const inst = new THREE.InstancedMesh(geo, mat, list.length);
      list.forEach((s, k) => {
        // A thin vertical strip on one face of each building.
        const off = s.edge * s.w * 0.49;
        dummy.position.set(s.x + Math.cos(s.rot) * off, s.y, s.z - Math.sin(s.rot) * off);
        dummy.rotation.set(0, s.rot, 0);
        dummy.scale.set(0.35, s.h, 0.35);
        dummy.updateMatrix();
        inst.setMatrixAt(k, dummy.matrix);
      });
      inst.instanceMatrix.needsUpdate = true;
      this.scene.add(inst);
    });

    // Beacons as a blinking Points cloud
    const beaconGeo = new THREE.BufferGeometry().setFromPoints(beaconPositions);
    this.beaconMat = new THREE.PointsMaterial({
      color: 0xff3344, size: 3.2, map: this.textures.glowPink, transparent: true,
      opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true, fog: false,
    });
    this.scene.add(new THREE.Points(beaconGeo, this.beaconMat));

    // Crown ring on the tallest near tower + signature spire
    this._buildLandmarks();

    // Billboards + neon signs
    this._buildSignage();
  }

  _buildLandmarks() {
    const rnd = this.rnd;
    // colossal arcology tower
    const towerX = 96, towerZ = -300;
    const tower = new THREE.Group();
    const towerMat = new THREE.MeshStandardMaterial({
      color: 0x121a22, roughness: 0.55, metalness: 0.7, envMapIntensity: 0.8,
      emissive: 0x0a2230, emissiveIntensity: 0.6,
    });
    const body = new THREE.Mesh(new THREE.CylinderGeometry(16, 30, 300, 8), towerMat);
    body.position.y = 80;
    tower.add(body);
    const crownMat = new THREE.MeshBasicMaterial({ color: 0x5ff6ff, toneMapped: false, transparent: true, opacity: 0.7 });
    for (let i = 0; i < 6; i++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(18 - i * 1.6, 0.22, 6, 40), crownMat);
      ring.rotation.x = Math.PI / 2;
      ring.position.y = 150 + i * 12;
      tower.add(ring);
    }
    for (let i = 0; i < 12; i++) {
      const band = new THREE.Mesh(
        new THREE.BoxGeometry(1.4, 150, 1.4),
