    // handguard / barrel shroud
    const shroud = box(0.105, 0.115, 0.46, polymer, 0, 0.005, -0.62);
    this.root.add(shroud);
    for (let i = 0; i < 6; i++) {
      this.root.add(box(0.112, 0.014, 0.05, darkMetal, 0, 0.045, -0.45 - i * 0.065));
