    this.root.add(box(0.012, 0.02, 0.1, glow, 0.09, -0.01, -0.22));
    // little heat sink fins
    for (let i = 0; i < 5; i++) {
      this.root.add(box(0.07, 0.045, 0.008, darkMetal, 0, 0.06, 0.18 + i * 0.028));
