    rSleeve.position.set(0.03, -0.23, 0.2);
    rArm.add(rSleeve);
    const rPlate = box(0.1, 0.08, 0.12, glovePlate, 0.03, -0.14, 0.12);
    rPlate.rotation.x = 0.4;
    rArm.add(rPlate);
    // wrist display
    const display = box(0.07, 0.035, 0.005, new THREE.MeshBasicMaterial({ color: 0x2effcf, toneMapped: false }), 0.03, -0.1, 0.18);
    display.rotation.x = 0.6;
    rArm.add(display);
