    const lArm = new THREE.Group();
    const lSleeve = new THREE.Mesh(new THREE.CapsuleGeometry(0.06, 0.34, 6, 10), sleeve);
    lSleeve.rotation.set(1.28, 0.0, -0.18);
    lSleeve.position.set(-0.08, -0.28, -0.44);
