export class EnemyManager {
  constructor(scene, world, fx, audio, callbacks = {}) {
    this.scene = scene;
    this.world = world;
    this.fx = fx;
    this.audio = audio;
    this.enemies = [];
    this.projectiles = [];
    this.onDamagePlayer = callbacks.onDamagePlayer || (() => {});
    this.onKill = callbacks.onKill || (() => {});
    this.colliders = world.colliders;
    this.projectileGeo = new THREE.SphereGeometry(0.13, 8, 6);
    this.projectileCoreMat = new THREE.MeshBasicMaterial({ color: 0xfff0c0, toneMapped: false });
    this.projectileTrailTex = glowPink;
    this.projectileMats = {
      wasp: new THREE.MeshBasicMaterial({ color: 0xff5aa8, toneMapped: false }),
      warden: new THREE.MeshBasicMaterial({ color: 0xffb43c, toneMapped: false }),
      titan: new THREE.MeshBasicMaterial({ color: 0xff4d5e, toneMapped: false }),
    };
    this.projectileGlowMats = {
      wasp: new THREE.SpriteMaterial({ map: glowPink, color: 0xff2e88, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false }),
      warden: new THREE.SpriteMaterial({ map: glowAmber, color: 0xffb43c, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false }),
      titan: new THREE.SpriteMaterial({ map: glowRed, color: 0xff4d5e, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false }),
    };
    this.raycaster = new THREE.Raycaster();
    this._tmp = new THREE.Vector3();
  }

  spawn(type, position, wave) {
    const e = new Enemy(this.scene, type, position, wave, this.world);
    this.enemies.push(e);
    return e;
  }

  clear() {
    for (const e of this.enemies) e.dispose();
    this.enemies.length = 0;
    for (const p of this.projectiles) this.scene.remove(p.mesh);
    this.projectiles.length = 0;
  }

  fire(enemy, from, target, speed, damage, isBig) {
    const dir = new THREE.Vector3().subVectors(target, from).normalize();
    const mat = this.projectileMats[enemy.type] || this.projectileMats.wasp;
    const mesh = new THREE.Mesh(this.projectileGeo, mat);
    mesh.position.copy(from);
    const glow = new THREE.Sprite(this.projectileGlowMats[enemy.type] || this.projectileGlowMats.wasp);
    glow.scale.setScalar(isBig ? 1.6 : 1.0);
    mesh.add(glow);
    this.scene.add(mesh);
    this.projectiles.push({
      mesh, dir, speed, damage, life: 5, isBig,
      type: enemy.type,
      trailTimer: 0,
      color: enemy.def.color,
    });
    this.fx.spawnSparks(from, dir, 5, {
      color: new THREE.Color(enemy.def.color), speed: 3, size: 0.12, life: 0.25, gravity: 0, normalBias: 0.2,
    });
  }

  update(dt, t, player) {
    const list = this.enemies;
    for (let i = list.length - 1; i >= 0; i--) {
      const e = list[i];
      e.coolFlash(dt);
      e.update(dt, t, player, list, this.colliders, this._onFire);
      if (!e.alive && e.spawned && !e._counted) {
        e._counted = true;
        this._kill(e);
        list.splice(i, 1);
      }
    }

    // projectiles
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt;
      p.mesh.position.addScaledVector(p.dir, p.speed * dt);
      p.trailTimer -= dt;
      if (p.trailTimer <= 0) {
        p.trailTimer = 0.03;
        this.fx.spawnSparks(p.mesh.position, null, 1, {
          color: new THREE.Color(p.color), speed: 0.5, size: 0.13, life: 0.24, gravity: 0, spread: 0.2,
        });
      }
      const pos = p.mesh.position;
      const dx = pos.x - player.position.x;
      const dy = pos.y - (player.position.y - 0.35);
      const dz = pos.z - player.position.z;
      if (dx * dx + dy * dy + dz * dz < 1.25) {
        this.onDamagePlayer(p.damage, pos);
        this.fx.explosion(pos, 0.35, false);
        this.audio.explosion(false);
        this.scene.remove(p.mesh);
        this.projectiles.splice(i, 1);
        continue;
      }
      if (pos.y < 0.05 || Math.hypot(pos.x, pos.z) > 28 || p.life <= 0) {
        this.fx.impact(pos.clone().setY(0.05), new THREE.Vector3(0, 1, 0), p.color, true);
        this.scene.remove(p.mesh);
        this.projectiles.splice(i, 1);
      }
    }
    this._onFire = this._onFire || ((e, from, target, speed, damage, big) => this.fire(e, from, target, speed, damage, big));
  }

  _kill(e) {
    const pos = e.group.position.clone();
    pos.y += e.type === 'titan' ? 3.5 : e.type === 'wasp' ? 0.2 : 1.6;
    const scale = e.type === 'titan' ? 2.6 : e.type === 'warden' ? 1.3 : 0.8;
    this.fx.explosion(pos, scale, e.type === 'titan');
    this.audio.explosion(e.type === 'titan');
    this.onKill(e, pos);
    e.dispose();
  }

  raycast(origin, direction, maxDist = 120) {
    this.raycaster.set(origin, direction);
    this.raycaster.far = maxDist;
    const objects = [];
    for (const e of this.enemies) if (e.alive && e.spawned) objects.push(e.group);
    const hits = this.raycaster.intersectObjects(objects, true);
    for (const h of hits) {
      let o = h.object;
      while (o && !o.userData.enemy) o = o.parent;
      if (o && o.userData.enemy && o.userData.enemy.alive) {
        return {
          enemy: o.userData.enemy,
          point: h.point,
          distance: h.distance,
          crit: !!h.object.userData.crit,
          normal: h.face ? h.face.normal.clone().transformDirection(h.object.matrixWorld) : new THREE.Vector3(0, 1, 0),
        };
      }
    }
    return null;
  }

  countAlive() {
    let n = 0;
    for (const e of this.enemies) if (e.alive) n++;
    return n;
  }

  getEnemyPositions() {
    return this.enemies.filter(e => e.alive && e.spawned).map(e => ({
      x: e.group.position.x, z: e.group.position.z, type: e.type,
    }));
  }
}

/* Unified desktop + touch input. */

export class Input {
  constructor(canvas, options = {}) {
    this.canvas = canvas;
    this.keys = new Set();
    this.pressed = new Set();
    this.firing = false;
    this.aiming = false;
    this.lookDelta = { x: 0, y: 0 };
    this.move = { x: 0, y: 0 };
    this.jumpQueued = false;
    this.reloadQueued = false;
    this.locked = false;
    this.enabled = false;
    this.sensitivity = 0.0022;
    this.onPause = options.onPause || (() => {});
    this.onLockChange = options.onLockChange || (() => {});
    this.isTouch = matchMedia('(hover: none), (pointer: coarse)').matches;

    this._bindKeyboard();
    this._bindMouse();
    this._bindTouch();
  }

  _bindKeyboard() {
    window.addEventListener('keydown', (e) => {
      if (e.code === 'Escape') {
        if (this.locked) document.exitPointerLock();
        else this.onPause();
        return;
      }
      if (!this.enabled) return;
      if (['Space', 'KeyW', 'KeyA', 'KeyS', 'KeyD', 'KeyR', 'ShiftLeft', 'ShiftRight'].includes(e.code)) e.preventDefault();
      if (!this.keys.has(e.code)) this.pressed.add(e.code);
      this.keys.add(e.code);
      if (e.code === 'KeyR') this.reloadQueued = true;
      if (e.code === 'Space') this.jumpQueued = true;
    });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.firing = false;
      this.aiming = false;
      if (this.enabled && this.locked) document.exitPointerLock();
    });
  }

  _bindMouse() {
    document.addEventListener('pointerlockchange', () => {
      this.locked = document.pointerLockElement === this.canvas;
      this.onLockChange(this.locked);
      if (!this.locked) {
        this.firing = false;
        this.aiming = false;
      }
    });
    document.addEventListener('mousemove', (e) => {
      if (!this.locked) return;
      this.lookDelta.x += e.movementX;
      this.lookDelta.y += e.movementY;
    });
    document.addEventListener('mousedown', (e) => {
      if (!this.locked || !this.enabled) return;
      if (e.button === 0) this.firing = true;
      if (e.button === 2) this.aiming = true;
    });
    document.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.firing = false;
      if (e.button === 2) this.aiming = false;
    });
    document.addEventListener('contextmenu', (e) => e.preventDefault());
  }

  _bindTouch() {
    const joystick = document.getElementById('joystick');
    const knob = document.getElementById('joystick-knob');
    const lookZone = document.getElementById('look-zone');
    const fireBtn = document.getElementById('btn-fire');
    const aimBtn = document.getElementById('btn-aim');
    const reloadBtn = document.getElementById('btn-reload');
    const jumpBtn = document.getElementById('btn-jump');
    if (!joystick || !knob) return;

    let joyId = null, joyCenter = null;
    const joyRadius = 40;

    const startJoy = (e) => {
      e.preventDefault();
      if (joyId !== null) return;
      joyId = e.pointerId;
      const r = joystick.getBoundingClientRect();
      joyCenter = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
      joystick.setPointerCapture(e.pointerId);
      moveJoy(e);
    };
    const moveJoy = (e) => {
      if (e.pointerId !== joyId || !joyCenter) return;
      e.preventDefault();
      let dx = e.clientX - joyCenter.x;
      let dy = e.clientY - joyCenter.y;
      const len = Math.hypot(dx, dy);
      if (len > joyRadius) { dx = (dx / len) * joyRadius; dy = (dy / len) * joyRadius; }
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
      this.move.x = dx / joyRadius;
      this.move.y = -dy / joyRadius;
    };
    const endJoy = (e) => {
      if (e.pointerId !== joyId) return;
      joyId = null; joyCenter = null;
      knob.style.transform = 'translate(0px, 0px)';
      this.move.x = 0; this.move.y = 0;
    };
    joystick.addEventListener('pointerdown', startJoy);
    joystick.addEventListener('pointermove', moveJoy);
    joystick.addEventListener('pointerup', endJoy);
    joystick.addEventListener('pointercancel', endJoy);

    let lookId = null, lastX = 0, lastY = 0;
    lookZone.addEventListener('pointerdown', (e) => {
      if (lookId !== null) return;
      e.preventDefault();
      lookId = e.pointerId;
      lastX = e.clientX; lastY = e.clientY;
      lookZone.setPointerCapture(e.pointerId);
    });
    lookZone.addEventListener('pointermove', (e) => {
      if (e.pointerId !== lookId) return;
      e.preventDefault();
      this.lookDelta.x += (e.clientX - lastX) * 1.5;
      this.lookDelta.y += (e.clientY - lastY) * 1.5;
      lastX = e.clientX; lastY = e.clientY;
    });
    const endLook = (e) => { if (e.pointerId === lookId) lookId = null; };
    lookZone.addEventListener('pointerup', endLook);
    lookZone.addEventListener('pointercancel', endLook);

    const holdBtn = (el, onDown, onUp) => {
      el.addEventListener('pointerdown', (e) => { e.preventDefault(); el.setPointerCapture(e.pointerId); onDown(); });
      el.addEventListener('pointerup', (e) => { e.preventDefault(); onUp?.(); });
      el.addEventListener('pointercancel', () => onUp?.());
      el.addEventListener('pointerleave', (e) => { if (e.buttons === 0) onUp?.(); });
    };
    holdBtn(fireBtn, () => { this.firing = true; }, () => { this.firing = false; });
    holdBtn(aimBtn, () => { this.aiming = true; }, () => { this.aiming = false; });
    reloadBtn.addEventListener('pointerdown', (e) => { e.preventDefault(); this.reloadQueued = true; });
    jumpBtn.addEventListener('pointerdown', (e) => { e.preventDefault(); this.jumpQueued = true; });

    // tapping the scene also fires on desktop-ish touch hybrids is avoided;
    // the dedicated fire button keeps aiming/strafe fingers free.
  }

  requestLock() {
    if (this.isTouch) return;
    this.canvas.requestPointerLock?.();
  }

  consumeLook() {
    const d = { x: this.lookDelta.x, y: this.lookDelta.y };
    this.lookDelta.x = 0;
    this.lookDelta.y = 0;
    return d;
  }

  consumePressed(code) {
    if (this.pressed.has(code)) { this.pressed.delete(code); return true; }
    return false;
  }

  reset() {
    this.keys.clear();
    this.pressed.clear();
    this.firing = false;
    this.aiming = false;
    this.lookDelta.x = 0;
    this.lookDelta.y = 0;
    this.move.x = 0;
    this.move.y = 0;
    this.jumpQueued = false;
    this.reloadQueued = false;
  }
}

import * as THREE from 'three';

export class Player {
  constructor(camera, world, audio) {
    this.camera = camera;
    this.world = world;
    this.audio = audio;
    this.position = new THREE.Vector3(0, 0, 15);
    this.velocity = new THREE.Vector3();
    this.eyeHeight = 1.7;
    this.radius = 0.42;
    this.yaw = 0;
    this.pitch = -0.02;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.shake = 0;
    this.bobPhase = 0;
    this.bobAmt = 0;
    this.health = 100;
    this.maxHealth = 100;
    this.armor = 50;
    this.maxArmor = 50;
    this.dead = false;
    this.onGround = true;
    this.velY = 0;
    this.ads = 0;
    this.sprinting = false;
    this.speed = 0;
    this.lastDamage = -99;
    this.lastHeal = 0;
    this.stepDistance = 0;
    this.time = 0;
    this.damageTakenThisFrame = 0;
    this.justDamaged = false;
    this.regenPulse = 0;
  }

  update(dt, t, input) {
    this.time = t;
    const look = input.consumeLook();
    const sens = 0.0022 * (1 - this.ads * 0.35);
    if (!this.dead) {
      this.yaw -= look.x * sens;
      this.pitch -= look.y * sens;
      this.pitch = THREE.MathUtils.clamp(this.pitch, -1.35, 1.35);
    }

    // recoil recovery
    this.recoilPitch *= Math.exp(-dt * 9);
    this.recoilYaw *= Math.exp(-dt * 9);
    this.shake *= Math.exp(-dt * 8);

    this.ads += ((input.aiming && !this.dead ? 1 : 0) - this.ads) * Math.min(1, dt * 12);

    let ix = 0, iy = 0;
    if (!this.dead) {
      if (input.keys.has('KeyW')) iy += 1;
      if (input.keys.has('KeyS')) iy -= 1;
      if (input.keys.has('KeyD')) ix += 1;
      if (input.keys.has('KeyA')) ix -= 1;
      ix += input.move.x;
      iy += input.move.y;
    }
    const mag = Math.hypot(ix, iy);
    if (mag > 1) { ix /= mag; iy /= mag; }

    const wantSprint = !this.dead && (input.keys.has('ShiftLeft') || input.keys.has('ShiftRight')) && iy > 0.35 && this.ads < 0.2;
    this.sprinting = wantSprint && mag > 0.1;

    let targetSpeed = 6.4;
    if (this.ads > 0.5) targetSpeed = 3.4;
    else if (this.sprinting) targetSpeed = 9.2;
    else if (iy < -0.2) targetSpeed = 4.6;

    const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    const desired = new THREE.Vector3()
      .addScaledVector(forward, iy)
      .addScaledVector(right, ix);
    if (desired.lengthSq() > 1) desired.normalize();
    desired.multiplyScalar(targetSpeed);

    const accel = this.onGround ? 16 : 5;
    this.velocity.x += (desired.x - this.velocity.x) * Math.min(1, dt * accel);
    this.velocity.z += (desired.z - this.velocity.z) * Math.min(1, dt * accel);
    this.speed = Math.hypot(this.velocity.x, this.velocity.z);

    // jump + gravity
    if (input.jumpQueued) {
      input.jumpQueued = false;
      if (this.onGround && !this.dead) {
        this.velY = 6.1;
        this.onGround = false;
      }
    }
    this.velY -= 19 * dt;
    this.position.y += this.velY * dt;
    if (this.position.y <= 0) {
      if (!this.onGround && this.velY < -3) this.audio.step(true);
      this.position.y = 0;
      this.velY = 0;
      this.onGround = true;
    }

    // horizontal collision, axis separated
    const colliders = this.world.colliders;
    const moveX = this.velocity.x * dt;
    const moveZ = this.velocity.z * dt;
    if (!this._blocked(this.position.x + moveX, this.position.z, colliders)) this.position.x += moveX;
    else this.velocity.x *= 0.2;
    if (!this._blocked(this.position.x, this.position.z + moveZ, colliders)) this.position.z += moveZ;
    else this.velocity.z *= 0.2;

    // arena bounds
    const maxR = this.world.playerBounds;
    const r = Math.hypot(this.position.x, this.position.z);
    if (r > maxR) {
      this.position.x = (this.position.x / r) * maxR;
      this.position.z = (this.position.z / r) * maxR;
      this.velocity.x *= 0.4;
      this.velocity.z *= 0.4;
    }

    // head bob
    if (this.onGround && this.speed > 0.4) {
      this.bobPhase += dt * (this.sprinting ? 12.5 : 8.6) * Math.min(1, this.speed / 6);
      this.bobAmt += (Math.min(1, this.speed / 6.4) - this.bobAmt) * Math.min(1, dt * 8);
    } else {
      this.bobAmt += (0 - this.bobAmt) * Math.min(1, dt * 6);
    }
    const bobY = Math.sin(this.bobPhase * 2) * 0.025 * this.bobAmt;
    const bobX = Math.cos(this.bobPhase) * 0.018 * this.bobAmt;

    // footsteps
    this.stepDistance += this.speed * dt;
    const stride = this.sprinting ? 2.7 : 2.1;
    if (this.onGround && this.stepDistance > stride && this.speed > 1) {
      this.stepDistance = 0;
      this.audio.step(this.sprinting);
    }
    if (!this.onGround) this.stepDistance = 0;

    // camera transform
    const shakeX = (Math.random() - 0.5) * this.shake * 0.035;
    const shakeY = (Math.random() - 0.5) * this.shake * 0.035;
    this.camera.position.set(
      this.position.x + bobX * 0.6 + shakeX,
      this.position.y + this.eyeHeight + bobY + shakeY,
      this.position.z
    );
    this.camera.rotation.order = 'YXZ';
    this.camera.rotation.set(
      this.pitch + this.recoilPitch + (Math.random() - 0.5) * this.shake * 0.006,
      this.yaw + this.recoilYaw,
      Math.sin(this.bobPhase) * 0.004 * this.bobAmt
    );

    // FOV
    const baseFov = 76;
    const targetFov = baseFov - this.ads * 23 + (this.sprinting ? 5 : 0);
    if (Math.abs(this.camera.fov - targetFov) > 0.05) {
      this.camera.fov += (targetFov - this.camera.fov) * Math.min(1, dt * 10);
      this.camera.updateProjectionMatrix();
    }

    // regen
    const sinceDamage = t - this.lastDamage;
    this.justDamaged = false;
    if (!this.dead) {
      if (sinceDamage > 6 && this.health < this.maxHealth) {
        this.health = Math.min(this.maxHealth, this.health + dt * 9);
        this.regenPulse = 1;
      } else if (this.regenPulse > 0) {
        this.regenPulse = Math.max(0, this.regenPulse - dt);
      }
      if (sinceDamage > 8 && this.armor < this.maxArmor) {
        this.armor = Math.min(this.maxArmor, this.armor + dt * 5);
      }
    }
  }

  _blocked(x, z, colliders) {
    const r = this.radius;
    for (const c of colliders) {
      if (x > c.minX - r && x < c.maxX + r && z > c.minZ - r && z < c.maxZ + r) return true;
    }
    return false;
  }

  addRecoil(pitch, yaw = 0) {
    this.recoilPitch += pitch;
    this.recoilYaw += yaw;
  }

  addShake(v) {
    this.shake = Math.min(1.4, this.shake + v);
  }

  damage(amount, sourcePos) {
    if (this.dead) return 0;
    let dmg = amount;
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.55);
      this.armor -= absorbed;
      dmg -= absorbed;
    }
    this.health -= dmg;
    this.lastDamage = this.time;
    this.justDamaged = true;
    this.damageTakenThisFrame += amount;
    this.addShake(Math.min(0.6, amount / 40));
    this.audio.damage();
    if (this.health <= 0) {
      this.health = 0;
      this.dead = true;
    }
    return dmg;
  }

  reset() {
    this.position.set(0, 0, 15);
    this.velocity.set(0, 0, 0);
    this.yaw = 0;
    this.pitch = -0.02;
    this.health = this.maxHealth;
    this.armor = this.maxArmor;
    this.dead = false;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.shake = 0;
    this.ads = 0;
    this.velY = 0;
    this.onGround = true;
    this.lastDamage = -99;
    this.camera.fov = 76;
    this.camera.updateProjectionMatrix();
  }
}

import * as THREE from 'three';

export class HUD {
  constructor() {
    this.el = {
      hud: document.getElementById('hud'),
      healthBar: document.getElementById('health-bar'),
      healthNum: document.getElementById('health-num'),
      armorBar: document.getElementById('armor-bar'),
      armorNum: document.getElementById('armor-num'),
      ammo: document.getElementById('ammo'),
      ammoReserve: document.getElementById('ammo-reserve'),
      reloadFill: document.getElementById('reload-bar-fill'),
      reloadRing: document.getElementById('reload-ring'),
      reloadProgress: document.getElementById('reload-progress'),
      score: document.getElementById('score'),
      kills: document.getElementById('kills'),
      combo: document.getElementById('combo'),
      waveTitle: document.getElementById('wave-title'),
      waveSub: document.getElementById('wave-sub'),
      waveKicker: document.getElementById('wave-kicker'),
      waveBanner: document.getElementById('wave-banner'),
      objectiveSub: document.getElementById('objective-sub'),
      hitmarker: document.getElementById('hitmarker'),
      crosshair: document.getElementById('crosshair'),
      killFeed: document.getElementById('kill-feed'),
      damageNumbers: document.getElementById('damage-numbers'),
      damageFlash: document.getElementById('damage-flash'),
      healFlash: document.getElementById('heal-flash'),
      damageDirections: document.getElementById('damage-directions'),
      centerToast: document.getElementById('center-toast'),
      statusText: document.getElementById('status-text'),
      radar: document.getElementById('radar'),
      menu: document.getElementById('menu'),
      pause: document.getElementById('pause'),
      gameover: document.getElementById('gameover'),
      loading: document.getElementById('loading'),
      pauseWave: document.getElementById('pause-wave'),
      pauseScore: document.getElementById('pause-score'),
      pauseKills: document.getElementById('pause-kills'),
      finalWave: document.getElementById('final-wave'),
      finalScore: document.getElementById('final-score'),
      finalKills: document.getElementById('final-kills'),
      quality: document.getElementById('quality-readout'),
      fireMode: document.getElementById('fire-mode'),
    };
    this.radarCtx = this.el.radar.getContext('2d');
    this.dmgPool = [];
    this.dmgCursor = 0;
    for (let i = 0; i < 22; i++) {
      const d = document.createElement('div');
      d.className = 'dmg-num';
      d.style.display = 'none';
      this.el.damageNumbers.appendChild(d);
      this.dmgPool.push(d);
    }
    this.hitTimer = 0;
    this.waveTimer = 0;
    this.toastTimer = 0;
    this._lastHealth = -1;
    this._lastArmor = -1;
    this._lastAmmo = -1;
    this._v = new THREE.Vector3();
    this._radarT = 0;
  }

  setScore(score) { this.el.score.textContent = score.toLocaleString('en-US'); }
  setKills(kills) { this.el.kills.textContent = kills; }
  setCombo(mult) { this.el.combo.textContent = `x${mult.toFixed(mult % 1 ? 1 : 0)}`; }

  updateVitals(player) {
    const hp = Math.ceil(player.health);
    const ar = Math.ceil(player.armor);
    if (hp !== this._lastHealth) {
      this._lastHealth = hp;
      this.el.healthNum.textContent = hp;
      this.el.healthBar.style.width = `${Math.max(0, (hp / player.maxHealth) * 100)}%`;
      this.el.healthBar.classList.toggle('low', hp <= 35);
    }
    if (ar !== this._lastArmor) {
      this._lastArmor = ar;
      this.el.armorNum.textContent = ar;
      this.el.armorBar.style.width = `${Math.max(0, (ar / player.maxArmor) * 100)}%`;
    }
    this.el.damageFlash.classList.toggle('hit', player.justDamaged && player.damageTakenThisFrame > 0);
  }

  updateAmmo(weapon) {
    if (weapon.ammo !== this._lastAmmo) {
      this._lastAmmo = weapon.ammo;
      this.el.ammo.textContent = String(weapon.ammo).padStart(2, '0');
      this.el.ammo.classList.toggle('low', weapon.ammo <= 6);
      this.el.ammoReserve.textContent = weapon.reserve;
    }
    const progress = weapon.reloading ? Math.min(1, weapon.reloadT) : 0;
    this.el.reloadFill.style.width = `${progress * 100}%`;
    this.el.reloadRing.classList.toggle('show', weapon.reloading);
    this.el.reloadProgress.style.strokeDashoffset = String(113 - progress * 113);
    this.el.fireMode.textContent = weapon.reloading ? 'RELOADING' : (weapon.ads > 0.5 ? '5.56 AP · ADS' : '5.56 AP');
  }

  updateCrosshair(player, weapon) {
    const speedK = Math.min(1, player.speed / 6);
    const spread = 5 + weapon.recoil * 9 + speedK * 5 + (1 - weapon.ads) * 2;
    this.el.crosshair.style.setProperty('--gap', `${spread.toFixed(1)}px`);
    this.el.crosshair.classList.toggle('ads', weapon.ads > 0.55);
  }

  setObjective(remaining, wave) {
    this.el.objectiveSub.textContent = remaining > 0
      ? `HOSTILES REMAINING · ${String(remaining).padStart(2, '0')}`
      : `WAVE ${String(wave).padStart(2, '0')} CLEAR · REPOSITION`;
  }

  setStatus(text) { this.el.statusText.textContent = text; }

  showWave(kicker, title, sub, duration = 2.8) {
    this.el.waveKicker.textContent = kicker;
    this.el.waveTitle.textContent = title;
    this.el.waveSub.textContent = sub;
    this.el.waveBanner.classList.add('show');
    clearTimeout(this._waveTimeout);
    this._waveTimeout = setTimeout(() => this.el.waveBanner.classList.remove('show'), duration * 1000);
  }

  hideWave() {
    this.el.waveBanner.classList.remove('show');
  }

  toast(text, duration = 1600) {
    this.el.centerToast.textContent = text;
    this.el.centerToast.classList.add('show');
    clearTimeout(this._toastTimeout);
    this._toastTimeout = setTimeout(() => this.el.centerToast.classList.remove('show'), duration);
  }

  hitmarker(kill = false, crit = false) {
    const el = this.el.hitmarker;
    el.classList.remove('show', 'kill');
    void el.offsetWidth;
    el.classList.add('show');
    if (kill) el.classList.add('kill');
    clearTimeout(this._hitTimeout);
    this._hitTimeout = setTimeout(() => el.classList.remove('show', 'kill'), kill ? 220 : 100);
  }

  damageNumber(worldPos, camera, amount, crit) {
    const v = this._v.copy(worldPos).project(camera);
    if (v.z > 1 || v.z < -1) return;
    const w = window.innerWidth, h = window.innerHeight;
    const x = (v.x * 0.5 + 0.5) * w;
    const y = (-v.y * 0.5 + 0.5) * h;
    const el = this.dmgPool[this.dmgCursor];
    this.dmgCursor = (this.dmgCursor + 1) % this.dmgPool.length;
    el.className = `dmg-num${crit ? ' crit' : ''}`;
    el.textContent = crit ? `${Math.round(amount)}!` : `${Math.round(amount)}`;
    el.style.display = 'block';
    el.style.left = `${x + (Math.random() - 0.5) * 20}px`;
    el.style.top = `${y - 10 + (Math.random() - 0.5) * 12}px`;
    el.style.animation = 'none';
    void el.offsetWidth;
    el.style.animation = '';
    clearTimeout(el._timeout);
    el._timeout = setTimeout(() => { el.style.display = 'none'; }, 720);
  }

  killFeed(name, points, crit) {
    const item = document.createElement('div');
    item.className = 'feed-item';
    item.innerHTML = `<span class="tag">${crit ? 'CRIT' : 'ELIM'}</span> ${name} <span class="pts">+${points}</span>`;
    this.el.killFeed.appendChild(item);
    setTimeout(() => item.remove(), 3200);
    while (this.el.killFeed.children.length > 4) this.el.killFeed.firstChild.remove();
  }

  damageDirection(angle) {
    const el = document.createElement('div');
    el.className = 'damage-dir';
    el.style.transform = `rotate(${angle}rad)`;
    this.el.damageDirections.appendChild(el);
    setTimeout(() => el.remove(), 1050);
  }

  healFlash() {
    this.el.healFlash.classList.add('on');
    setTimeout(() => this.el.healFlash.classList.remove('on'), 220);
  }

  showMenu(v) { this.el.menu.classList.toggle('hidden', !v); }
  showPause(v) { this.el.pause.classList.toggle('hidden', !v); }
  showGameOver(v) { this.el.gameover.classList.toggle('hidden', !v); }
  hideLoading() {
    this.el.loading.classList.add('done');
    setTimeout(() => this.el.loading.classList.add('hidden'), 700);
  }
  setQuality(text) { this.el.quality.textContent = text; }

  pauseStats(wave, score, kills) {
    this.el.pauseWave.textContent = String(wave).padStart(2, '0');
    this.el.pauseScore.textContent = score.toLocaleString('en-US');
    this.el.pauseKills.textContent = kills;
  }

  gameOverStats(wave, score, kills) {
    this.el.finalWave.textContent = wave;
    this.el.finalScore.textContent = score.toLocaleString('en-US');
    this.el.finalKills.textContent = kills;
  }

  drawRadar(enemies, player, corePos, dt) {
    const ctx = this.radarCtx;
    const W = 190, H = 190, cx = 95, cy = 95;
    const maxRange = 40;
    const scale = 78 / maxRange;
    this._radarT += dt;
    ctx.clearRect(0, 0, W, H);

    // circular backdrop
    const bg = ctx.createRadialGradient(cx, cy, 4, cx, cy, 92);
    bg.addColorStop(0, 'rgba(12,40,52,0.9)');
    bg.addColorStop(0.75, 'rgba(6,18,26,0.82)');
    bg.addColorStop(1, 'rgba(3,10,14,0.9)');
    ctx.fillStyle = bg;
    ctx.beginPath(); ctx.arc(cx, cy, 92, 0, 7); ctx.fill();

    // rings
    ctx.strokeStyle = 'rgba(95,246,255,0.16)';
    ctx.lineWidth = 1;
    for (let i = 1; i <= 3; i++) {
      ctx.beginPath(); ctx.arc(cx, cy, (78 / 3) * i, 0, 7); ctx.stroke();
    }
    ctx.beginPath(); ctx.moveTo(cx - 84, cy); ctx.lineTo(cx + 84, cy); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx, cy - 84); ctx.lineTo(cx, cy + 84); ctx.stroke();

    // sweep
    const sweep = this._radarT * 1.6;
    const grad = ctx.createConicGradient(sweep - 0.5, cx, cy);
    grad.addColorStop(0, 'rgba(95,246,255,0.0)');
    grad.addColorStop(0.06, 'rgba(95,246,255,0.18)');
    grad.addColorStop(0.12, 'rgba(95,246,255,0.0)');
    grad.addColorStop(1, 'rgba(95,246,255,0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(cx, cy, 92, 0, 7); ctx.fill();

    const yaw = player.yaw;
    const cos = Math.cos(yaw), sin = Math.sin(yaw);
    const project = (wx, wz) => {
      const dx = wx - player.position.x;
      const dz = wz - player.position.z;
      // forward = (-sin, -cos), right = (cos, -sin)
      const lx = dx * cos - dz * sin;
      const lz = -dx * sin - dz * cos;
      return { x: cx + lx * scale, y: cy - lz * scale, d: Math.hypot(dx, dz) };
    };

    // core objective
    if (corePos) {
      const p = project(corePos.x, corePos.z);
      if (p.d < maxRange * 1.2) {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(Math.PI / 4);
        ctx.fillStyle = 'rgba(95,246,255,0.75)';
        ctx.shadowColor = '#5ff6ff'; ctx.shadowBlur = 8;
        ctx.fillRect(-3, -3, 6, 6);
        ctx.restore();
      }
    }

    // enemy blips
    for (const e of enemies) {
      const p = project(e.x, e.z);
      if (p.d > maxRange) continue;
      const color = e.type === 'titan' ? '#ff4d5e' : e.type === 'warden' ? '#ffb43c' : '#ff2e88';
      ctx.fillStyle = color;
      ctx.shadowColor = color;
      ctx.shadowBlur = 7;
      ctx.beginPath(); ctx.arc(p.x, p.y, e.type === 'wasp' ? 2.6 : 4, 0, 7); ctx.fill();
      ctx.shadowBlur = 0;
    }

    // player arrow
    ctx.save();
    ctx.translate(cx, cy);
    ctx.fillStyle = '#dffcff';
    ctx.shadowColor = '#5ff6ff'; ctx.shadowBlur = 9;
    ctx.beginPath();
    ctx.moveTo(0, -7);
    ctx.lineTo(5, 6);
    ctx.lineTo(0, 3);
    ctx.lineTo(-5, 6);
    ctx.closePath(); ctx.fill();
    ctx.restore();

    // rim
    ctx.strokeStyle = 'rgba(95,246,255,0.34)';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(cx, cy, 92, 0, 7); ctx.stroke();
  }
}

