import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const url = process.env.URL || 'http://localhost:3002/';
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 60000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto(url, { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(1500);
await page.screenshot({ path: join(out, 'z-menu.png') });
await page.locator('#start-btn').click();
await page.waitForTimeout(9000);
const stats = await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  return {
