    moon.shadow.camera.left = -34;
    moon.shadow.camera.right = 34;
    moon.shadow.camera.top = 34;
    moon.shadow.camera.bottom = -34;
    moon.shadow.camera.near = 20;
    moon.shadow.camera.far = 260;
    moon.shadow.bias = -0.0005;
    this.scene.add(moon);
    this.moonLight = moon;

    // core key light
