    key.position.set(0, 22, 4);
    key.target.position.set(0, 0, 0);
    key.castShadow = true;
    key.shadow.mapSize.set(1024, 1024);
    key.shadow.bias = -0.001;
    this.scene.add(key);
    this.scene.add(key.target);
    this.keyLight = key;

    // coloured fills (no shadows)
    const pinks = [
