import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const url = process.env.URL || 'http://localhost:3002/';
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 60000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto(url, { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(1200);
await page.locator('#start-btn').click();
await page.waitForTimeout(22000);
const stats = await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  const list = N.enemies.enemies.filter(e => e.alive);
  return {
    mode: N.game.mode, wave: N.game.wave, enemies: list.length,
    types: list.map(e => e.type),
    player: N.player.position.toArray(),
    calls: N.renderer.info.render.calls, tris: N.renderer.info.render.triangles,
    geometries: N.renderer.info.memory.geometries, textures: N.renderer.info.memory.textures,
    sceneChildren: N.world.scene.children.length,
    score: N.game.score, kills: N.game.kills,
  };
});
console.log('STATS', JSON.stringify(stats));
const angles = [0, 0.8, Math.PI / 2, Math.PI, -Math.PI / 2];
for (let i = 0; i < angles.length; i++) {
  await page.evaluate((a) => {
    const N = window.__NIGHTFALL__;
    N.player.yaw = a; N.player.pitch = -0.02;
  }, angles[i]);
  await page.waitForTimeout(2000);
  await page.screenshot({ path: join(out, `y-angle${i}.png`) });
}
// enemy close-up
const info = await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  const list = N.enemies.enemies.filter(e => e.alive && e.spawned);
  if (!list.length) return null;
  const e = list[0];
  const p = e.group.position;
  N.player.position.set(p.x + 5.5, 0, p.z + 5.5);
  N.player.yaw = Math.atan2(p.x - (p.x + 5.5), p.z - (p.z + 5.5));
  N.player.pitch = -0.06;
  return { type: e.type, hp: e.hp, pos: p.toArray() };
});
console.log('ENEMY', JSON.stringify(info));
await page.waitForTimeout(2500);
await page.screenshot({ path: join(out, 'y-enemy.png') });
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

