import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const url = process.env.URL || 'http://localhost:3002/';
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 60000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto(url, { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(1200);
await page.locator('#start-btn').click();
await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  N.game.waveDelay = 999;
  N.game.wave = 1;
  N.enemies.clear();
  const spawn = (type, x, z) => {
    const e = N.enemies.spawn(type, new (N.enemies.enemies[0]?.group.position.constructor || Object)(x, 0, z), 1);
    e.spawned = true; e.spawnT = 1; e.group.visible = true; e.hpBar.visible = true;
    return e;
  };
  // use simple vector clone from player position
  const base = N.player.position.clone();
  const make = (type, x, z) => {
    const pos = base.clone(); pos.set(x, 0, z);
    const e = N.enemies.spawn(type, pos, 1);
    e.spawned = true; e.spawnT = 1; e.group.visible = true; e.hpBar.visible = true;
    return e;
  };
  make('wasp', -4.5, 8);
  make('warden', 0, 7);
  make('titan', 6, 5);
});
await page.waitForTimeout(4000);
await page.screenshot({ path: join(out, 'x-enemies.png') });
// wasp close-up
for (const [i, type, x, z] of [[0, 'wasp', -1.5, 8], [1, 'warden', 0, 8], [2, 'titan', 0, 11]]) {
  await page.evaluate(({ type, x, z }) => {
    const N = window.__NIGHTFALL__;
    N.enemies.clear();
    const pos = N.player.position.clone(); pos.set(x, 0, z);
    const e = N.enemies.spawn(type, pos, 1);
    e.spawned = true; e.spawnT = 1; e.group.visible = true; e.hpBar.visible = false;
    N.player.position.set(x, 0, z + 7);
    N.player.yaw = 0; N.player.pitch = type === 'titan' ? 0.12 : 0.02;
  }, { type, x, z });
  await page.waitForTimeout(2200);
  await page.screenshot({ path: join(out, `x-${type}.png`) });
}
const fps = await page.evaluate(() => new Promise(res => {
  let n = 0; const t0 = performance.now();
  function f() { n++; if (performance.now() - t0 < 3000) requestAnimationFrame(f); else res(n / 3); }
  requestAnimationFrame(f);
}));
console.log('FPS', fps.toFixed(1));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

