import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 60000 });
const page = await browser.newPage({ viewport: { width: 1000, height: 640 } });
const errors = [];
page.on('pageerror', e => errors.push(e.stack || e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(1200);
await page.locator('#start-btn').click();
await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  N.game.waveDelay = 0.01;
});
await page.waitForTimeout(12000);
const state = await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  return { wave: N.game.wave, active: N.game.waveActive, alive: N.enemies.countAlive(), queue: N.game.spawnQueue.length, mode: N.game.mode };
});
console.log('STATE', state);
console.log('ERRCOUNT', errors.length);
console.log(errors.slice(0, 3).join('\n---\n'));
await browser.close();

