import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 60000 });

async function newPage(ctx, width, height) {
  const page = await ctx.newPage();
  await page.setViewportSize({ width, height });
  const errors = [];
  page.on('pageerror', e => errors.push(e.stack || e.message));
  page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push('CONSOLE ' + m.text()); });
  return { page, errors };
}

const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const { page, errors } = await newPage(ctx, 1440, 900);
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(1200);
await page.locator('#start-btn').click();
await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  N.game.waveDelay = 0.01;
  N.game.wave = 0;
});
await page.waitForFunction(() => window.__NIGHTFALL__.game.waveActive === true, { timeout: 120000 });
console.log('WAVE ACTIVE');

// stage a readable firefight in front of the player
await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  N.enemies.clear();
  const base = N.player.position.clone();
  const add = (type, x, z, hpPct) => {
    const pos = base.clone(); pos.set(x, 0, z);
    const e = N.enemies.spawn(type, pos, N.game.wave || 1);
    e.spawned = true; e.spawnT = 1; e.group.visible = true;
    e.health = e.maxHealth * hpPct;
    return e;
  };
  add('wasp', -6.5, 7.5, 0.65);
  add('warden', 0, 8.5, 0.8);
  add('titan', 7.5, 6.5, 0.9);
  N.game.wave = 1;
  N.hud.setObjective(3, 1);
});
await page.waitForTimeout(2500);
await page.screenshot({ path: join(out, 'final-action.png') });

// firing / kill test
const combat = await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  N.enemies.clear();
  const pos = N.player.position.clone(); pos.set(0, 0, 8);
  const e = N.enemies.spawn('wasp', pos, 2);
  e.spawned = true; e.spawnT = 1; e.group.visible = true;
  N.player.position.set(0, 0, 15);
  N.player.yaw = 0;
  N.player.pitch = -0.02;
  const beforeAmmo = N.weapon.ammo;
  const beforeKills = N.game.kills;
  for (let i = 0; i < 3; i++) {
    N.weapon.cooldown = 0;
    if (N.weapon.tryFire()) N.fireShot();
  }
  return { beforeAmmo, afterAmmo: N.weapon.ammo, beforeKills, enemyHp: e.health };
});
await page.waitForTimeout(1500);
const afterCombat = await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  return { ammo: N.weapon.ammo, kills: N.game.kills, score: N.game.score, alive: N.enemies.countAlive(), combo: N.game.combo, ammoText: document.querySelector('#ammo-count')?.textContent };
});
console.log('COMBAT', JSON.stringify({ combat, afterCombat }));

// pause overlay
await page.evaluate(() => window.__NIGHTFALL__.pauseGame());
await page.waitForTimeout(800);
await page.screenshot({ path: join(out, 'final-pause.png') });
const paused = await page.evaluate(() => ({ mode: window.__NIGHTFALL__.game.mode, visible: !document.querySelector('#pause').classList.contains('hidden') }));
await page.evaluate(() => window.__NIGHTFALL__.resumeGame());
await page.waitForTimeout(500);
const resumed = await page.evaluate(() => window.__NIGHTFALL__.game.mode);
console.log('PAUSE', JSON.stringify({ paused, resumed }));

// game over + restart
await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  N.damagePlayer(999, N.player.position.clone());
});
await page.waitForTimeout(1600);
await page.screenshot({ path: join(out, 'final-gameover.png') });
const over = await page.evaluate(() => ({ mode: window.__NIGHTFALL__.game.mode, visible: !document.querySelector('#gameover').classList.contains('hidden'), health: window.__NIGHTFALL__.player.health }));
await page.locator('#restart-btn').click();
await page.waitForTimeout(1500);
const restarted = await page.evaluate(() => {
  const N = window.__NIGHTFALL__;
  return { mode: N.game.mode, wave: N.game.wave, score: N.game.score, kills: N.game.kills, health: N.player.health, ammo: N.weapon.ammo, pos: N.player.position.toArray() };
});
console.log('GAMEOVER', JSON.stringify({ over, restarted }));

// performance & scene complexity (reset info around one frame)
const perf = await page.evaluate(() => new Promise(res => {
  const N = window.__NIGHTFALL__;
  let frames = 0; const t0 = performance.now();
  N.renderer.info.autoReset = false;
  N.renderer.info.reset();
  function f() {
    frames++;
    if (performance.now() - t0 < 2500) requestAnimationFrame(f);
    else {
      const info = { calls: N.renderer.info.render.calls, tris: N.renderer.info.render.triangles, frames, seconds: (performance.now() - t0) / 1000 };
      N.renderer.info.autoReset = true;
      res(info);
    }
  }
  requestAnimationFrame(f);
}));
console.log('PERF', JSON.stringify(perf));
console.log('DESKTOP ERRORS', JSON.stringify(errors.slice(0, 5)));

// mobile
const mctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
const mp = await mctx.newPage();
const mErrors = [];
mp.on('pageerror', e => mErrors.push(e.stack || e.message));
await mp.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await mp.waitForFunction(() => document.fonts.status === 'loaded');
await mp.waitForTimeout(1500);
await mp.screenshot({ path: join(out, 'final-mobile-menu.png') });
await mp.locator('#start-btn').click();
await mp.evaluate(() => { window.__NIGHTFALL__.game.waveDelay = 0.01; });
await mp.waitForTimeout(5000);
await mp.screenshot({ path: join(out, 'final-mobile-game.png') });
const mobile = await mp.evaluate(() => ({
  mode: window.__NIGHTFALL__.game.mode,
  touch: window.__NIGHTFALL__.input.isTouch,
  controls: getComputedStyle(document.querySelector('#mobile-controls')).display,
  hud: !document.querySelector('#hud').classList.contains('hidden'),
  startHidden: document.querySelector('#menu').classList.contains('hidden'),
}));
console.log('MOBILE', JSON.stringify(mobile));
console.log('MOBILE ERRORS', JSON.stringify(mErrors.slice(0, 5)));
await browser.close();

