import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 60000 });

const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + (e.stack || e.message)));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
page.on('crash', () => errors.push('PAGE CRASHED'));
const t0 = Date.now();
await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded', timeout: 120000 });
console.log('DOM', Date.now() - t0, 'ms');
try {
  await page.waitForFunction(() => {
    const b = document.querySelector('#start-btn');
    const l = document.querySelector('#loading');
    return b && (!l || l.classList.contains('done') || getComputedStyle(l).opacity === '0');
  }, { timeout: 180000 });
  console.log('READY', Date.now() - t0, 'ms');
} catch (e) {
  console.log('READY TIMEOUT', Date.now() - t0, 'ms');
}
const state = await page.evaluate(() => ({
  ready: document.readyState,
  loading: document.querySelector('#loading')?.className,
  menu: document.querySelector('#menu')?.className,
  btn: (() => { const b = document.querySelector('#start-btn'); if (!b) return null; const r = b.getBoundingClientRect(); const s = getComputedStyle(b); return { w: r.width, h: r.height, display: s.display, visibility: s.visibility, opacity: s.opacity }; })(),
  hasNightfall: !!window.__NIGHTFALL__,
}));
console.log('STATE', JSON.stringify(state));
await page.screenshot({ path: join(out, 'mobile-debug.png') });
try {
  await page.waitForSelector('#start-btn', { state: 'visible', timeout: 120000 });
  await page.locator('#start-btn').click({ timeout: 30000 });
  console.log('STARTED');
  await page.waitForTimeout(5000);
  await page.evaluate(() => { window.__NIGHTFALL__.game.waveDelay = 0.01; });
  await page.waitForTimeout(6000);
  await page.screenshot({ path: join(out, 'final-mobile-game.png') });
  const info = await page.evaluate(() => ({
    mode: window.__NIGHTFALL__.game.mode,
    touch: window.__NIGHTFALL__.input.isTouch,
    touchUi: getComputedStyle(document.querySelector('#touch-ui')).display,
    hud: !document.querySelector('#hud').classList.contains('hidden'),
    menuHidden: document.querySelector('#menu').classList.contains('hidden'),
    wave: window.__NIGHTFALL__.game.wave,
    alive: window.__NIGHTFALL__.enemies.countAlive(),
    ammo: window.__NIGHTFALL__.weapon.ammo,
  }));
  console.log('MOBILE', JSON.stringify(info));
  // pause button
  await page.locator('#pause-btn').click();
  await page.waitForTimeout(1200);
  await page.screenshot({ path: join(out, 'final-mobile-pause.png') });
  console.log('PAUSE MODE', await page.evaluate(() => window.__NIGHTFALL__.game.mode));
} catch (e) {
  console.log('MOBILE FAIL', e.message.split('\n')[0]);
}
console.log('ERRORS', JSON.stringify(errors.slice(0, 6)));
await browser.close();

